34	// csrc/kernels/hip/gfx942/models/attention.hip.h
35	// Shared attention kernel for gfx942 (CDNA3 / MI300X). Serves both Decoder
36	// (causal, seq_len=4) and ViT (non-causal, seq_len=17) via kCausal template.
37	//
38	// Key differences from sm_90:
39	//   - Wave size 64: reductions use the explicit __builtin_amdgcn_mov_dpp
40	//     row-shift + row-broadcast butterfly (NOT __shfl_xor, which can lower to a
41	//     ds_bpermute LDS round-trip) — see §5.0 / amd::wave_reduce_add_dpp
42	//   - No WGMMA/TMA: BF16 MFMA via __builtin_amdgcn_mfma_f32_16x16x16bf16
43	//   - 64 KB LDS per CU (not 228 KB SMEM)
44	//   - FULL_WARP_MASK is 0 on HIP (all 64 lanes lockstep)
45	//   - CK FMHA gated behind WITH_CK; fallback to hand-written MFMA path
46	//   - Occupancy via GROK_WAVES_PER_EU / GROK_FLAT_WORK_GROUP_SIZE
47	//
48	// For grokking shapes (d_head=32, seq_len=4/17), QK^T fits in regs/LDS.
49	// One workgroup per (batch, head) pair.
50	#pragma once
