103	// -- External backend forward declarations ------------------------------------
104	#ifdef WITH_CK
105	template <typename ActT, int kHeadDim, bool kCausal>
106	hipError_t ck_fmha_forward(
107	    const ActT* q, const ActT* k, const ActT* v, ActT* out, ActT* softmax_lse,
108	    int batch, int n_heads, int seq_len, float scale, hipStream_t stream);
109	#endif
110	#ifdef WITH_AITER
111	template <typename ActT, int kHeadDim, bool kCausal>
112	hipError_t aiter_fmha_forward(
113	    const ActT* q, const ActT* k, const ActT* v, ActT* out, ActT* softmax_lse,
114	    int batch, int n_heads, int seq_len, float scale, hipStream_t stream);
115	#endif
