117	// -- LDS-based attention kernel (default for tiny seq_len) ---------------------
118	// One block per (batch, head). Wave-64 cooperative matmul. Max seq_len: 32.
119	template <typename ActT, int kHeadDim, bool kCausal>
120	__global__ void
121	GROK_FLAT_WORK_GROUP_SIZE(64, 256)
122	GROK_WAVES_PER_EU(1, 4)
123	lds_attention_fwd_kernel(
124	    const ActT* __restrict__ q,      // [B, H, N, D]
125	    const ActT* __restrict__ k,
126	    const ActT* __restrict__ v,
127	    ActT* __restrict__ out,
128	    float* __restrict__ softmax_lse,  // [B, H, N] or nullptr
129	    int seq_len, float scale
130	) {
131	    const int bh = blockIdx.x, tid = threadIdx.x;
132	    const int N = seq_len, D = kHeadDim;
133	    const int64_t base = static_cast<int64_t>(bh) * N * D;
134	    extern __shared__ float lds[];
135	    float* scores  = lds;
136	    float* row_max = scores + N * N;
137	    float* row_sum = row_max + N;
138	    // S = Q K^T * scale, optional causal mask
139	    for (int idx = tid; idx < N * N; idx += blockDim.x) {
140	        int i = idx / N, j = idx % N;
141	        if constexpr (kCausal) {
142	            // Unified mask sentinel (-1e30f), matching the sm_90 path and the
143	            // other gfx942 attention kernel (was -1e9f — inconsistent).
144	            if (j > i) { scores[idx] = -1e30f; continue; }
145	        }
146	        float dot = 0.0f;
147	        for (int d = 0; d < D; d++)
148	            dot += static_cast<float>(q[base + i * D + d])
149	                 * static_cast<float>(k[base + j * D + d]);
150	        scores[idx] = dot * scale;
151	    }
152	    __syncthreads();
153	    // Row-wise stable softmax
154	    for (int i = tid; i < N; i += blockDim.x) {
155	        float m = -1e30f;   // unified sentinel (matches sm_90 + CUTLASS softmax)
156	        for (int j = 0; j < N; j++) m = fmaxf(m, scores[i * N + j]);
157	        row_max[i] = m;
158	        float s = 0.0f;
159	        for (int j = 0; j < N; j++) {
160	            float e = expf(scores[i * N + j] - m);
161	            scores[i * N + j] = e;
162	            s += e;
163	        }
164	        float inv_s = 1.0f / fmaxf(s, 1e-12f);
165	        for (int j = 0; j < N; j++) scores[i * N + j] *= inv_s;
166	        row_sum[i] = s;
167	        if (softmax_lse != nullptr)
168	            softmax_lse[static_cast<int64_t>(bh) * N + i] = m + logf(fmaxf(s, 1e-12f));
169	    }
170	    __syncthreads();
171	    // Out = Softmax(S) * V
172	    for (int idx = tid; idx < N * D; idx += blockDim.x) {
173	        int i = idx / D, d = idx % D;
174	        float acc = 0.0f;
175	        for (int j = 0; j < N; j++)
176	            acc += scores[i * N + j] * static_cast<float>(v[base + j * D + d]);
177	        out[base + idx] = static_cast<ActT>(acc);
178	    }
179	}
180	
181	// -- Forward dispatch ----------------------------------------------------------
182	template <typename ActT, int kHeadDim, bool kCausal>
183	hipError_t attention_forward(
184	    const ActT* q, const ActT* k, const ActT* v,
185	    ActT* out, ActT* softmax_lse_act,
186	    int batch, int n_heads, int seq_len, float scale,
187	    hipStream_t stream
188	) {
189	    float* softmax_lse = reinterpret_cast<float*>(softmax_lse_act);
190	#ifdef WITH_CK
191	    return ck_fmha_forward<ActT, kHeadDim, kCausal>(
192	        q, k, v, out, reinterpret_cast<ActT*>(softmax_lse),
193	        batch, n_heads, seq_len, scale, stream);
194	#elif defined(WITH_AITER)
195	    return aiter_fmha_forward<ActT, kHeadDim, kCausal>(
196	        q, k, v, out, reinterpret_cast<ActT*>(softmax_lse),
197	        batch, n_heads, seq_len, scale, stream);
198	#else
199	    int grid = batch * n_heads;
200	    int block = WARP_SIZE * 2;  // 128 threads = 2 waves on CDNA3
201	    int N = seq_len;
202	    int lds_bytes = (N * N + 2 * N) * sizeof(float);
203	    lds_attention_fwd_kernel<ActT, kHeadDim, kCausal>
204	        <<<grid, block, lds_bytes, stream>>>(
205	            q, k, v, out, softmax_lse, seq_len, scale);
206	    return hipGetLastError();
207	#endif
208	}
209	
210	// -- Backward kernel ----------------------------------------------------------
211	// Recomputes attention weights from softmax_lse (log-sum-exp saved in fwd).
212	// dV = A^T dO, dA = dO V^T, backprop through softmax, dQ = dA' K * scale,
213	// dK = dA'^T Q * scale. All in LDS for these tiny sequence lengths.
214	
215	template <typename ActT, int kHeadDim, bool kCausal>
216	__global__
217	GROK_FLAT_WORK_GROUP_SIZE(64, 256)
218	GROK_WAVES_PER_EU(1, 4)
219	void lds_attention_bwd_kernel(
220	    const ActT* __restrict__ grad_out,   // [B, H, N, D]
221	    const ActT* __restrict__ q,
222	    const ActT* __restrict__ k,
223	    const ActT* __restrict__ v,
224	    const ActT* __restrict__ attn_out,   // saved forward output
225	    const float* __restrict__ softmax_lse, // [B, H, N]
226	    ActT* __restrict__ grad_q,
227	    ActT* __restrict__ grad_k,
228	    ActT* __restrict__ grad_v,
229	    int seq_len, float scale
230	) {
231	    const int bh = blockIdx.x, tid = threadIdx.x;
232	    const int N = seq_len, D = kHeadDim;
233	    const int64_t base = static_cast<int64_t>(bh) * N * D;
234	
235	    extern __shared__ float lds[];
236	    float* scores = lds;             // N * N (attention weights)
237	    float* dA     = scores + N * N;  // N * N (grad through attn weights)
238	
239	    // Recompute attention weights from softmax_lse
240	    for (int idx = tid; idx < N * N; idx += blockDim.x) {
241	        int i = idx / N, j = idx % N;
242	        if constexpr (kCausal) {
243	            if (j > i) { scores[idx] = 0.0f; continue; }
244	        }
245	        float dot = 0.0f;
246	        for (int d = 0; d < D; d++)
247	            dot += static_cast<float>(q[base + i * D + d])
248	                 * static_cast<float>(k[base + j * D + d]);
249	        float lse = softmax_lse[static_cast<int64_t>(bh) * N + i];
250	        scores[idx] = ptx_expf(dot * scale - lse);
251	    }
252	    __syncthreads();
253	
254	    // dV = A^T dO
255	    for (int idx = tid; idx < N * D; idx += blockDim.x) {
256	        int j = idx / D, d = idx % D;
257	        float acc = 0.0f;
258	        for (int i = 0; i < N; i++)
259	            acc += scores[i * N + j]
260	                 * static_cast<float>(grad_out[base + i * D + d]);
261	        grad_v[base + idx] = static_cast<ActT>(acc);
262	    }
263	    __syncthreads();
264	
265	    // dA = dO V^T
266	    for (int idx = tid; idx < N * N; idx += blockDim.x) {
267	        int i = idx / N, j = idx % N;
268	        float acc = 0.0f;
269	        for (int d = 0; d < D; d++)
270	            acc += static_cast<float>(grad_out[base + i * D + d])
271	                 * static_cast<float>(v[base + j * D + d]);
272	        dA[idx] = acc;
273	    }
274	    __syncthreads();
275	
276	    // Backprop through softmax: dS_ij = A_ij * (dA_ij - sum_k(A_ik * dA_ik))
277	    for (int i = tid; i < N; i += blockDim.x) {
278	        float dot_sum = 0.0f;
279	        for (int j = 0; j < N; j++)
280	            dot_sum += scores[i * N + j] * dA[i * N + j];
281	        for (int j = 0; j < N; j++) {
282	            float ds = scores[i * N + j] * (dA[i * N + j] - dot_sum) * scale;
283	            if constexpr (kCausal) { if (j > i) ds = 0.0f; }
284	            dA[i * N + j] = ds;  // reuse dA for dS
285	        }
286	    }
287	    __syncthreads();
288	
289	    // dQ = dS K
290	    for (int idx = tid; idx < N * D; idx += blockDim.x) {
291	        int i = idx / D, d = idx % D;
292	        float acc = 0.0f;
293	        for (int j = 0; j < N; j++)
294	            acc += dA[i * N + j] * static_cast<float>(k[base + j * D + d]);
295	        grad_q[base + idx] = static_cast<ActT>(acc);
296	    }
297	
298	    // dK = dS^T Q
299	    for (int idx = tid; idx < N * D; idx += blockDim.x) {
300	        int j = idx / D, d = idx % D;
301	        float acc = 0.0f;
302	        for (int i = 0; i < N; i++)
303	            acc += dA[i * N + j] * static_cast<float>(q[base + i * D + d]);
304	        grad_k[base + idx] = static_cast<ActT>(acc);
305	    }
306	}
307	
308	// -- Backward dispatch --------------------------------------------------------
309	template <typename ActT, int kHeadDim, bool kCausal>
310	hipError_t attention_backward(
311	    const ActT* grad_out,
312	    const ActT* q, const ActT* k, const ActT* v,
313	    const ActT* out, const ActT* softmax_lse_act,
314	    ActT* grad_q, ActT* grad_k, ActT* grad_v,
315	    int batch, int n_heads, int seq_len,
316	    float scale, hipStream_t stream
317	) {
318	    const float* softmax_lse = reinterpret_cast<const float*>(softmax_lse_act);
319	    int grid = batch * n_heads;
320	    int block = WARP_SIZE * 2;  // 128 threads = 2 waves on CDNA3
321	    int N = seq_len;
322	    int lds_bytes = 2 * N * N * sizeof(float);  // scores + dA
323	    lds_attention_bwd_kernel<ActT, kHeadDim, kCausal>
324	        <<<grid, block, lds_bytes, stream>>>(
325	            grad_out, q, k, v, out, softmax_lse,
326	            grad_q, grad_k, grad_v, seq_len, scale);
327	    return hipGetLastError();
328	}
