357	// (B) DEVICE pass — real hand-written AMDGCN forward+backward (§5).
358	// Compiled by the AMDGCN device pass only: the Stage-5 gate (__AMDGCN__, no
359	// hipcc) AND the hipcc device pass (__HIPCC__).
360	// ════════════════════════════════════════════════════════════════════════════
361	#if defined(__AMDGCN__) || defined(__HIPCC__) || defined(GROK_HIP_DEVICE)
362	#include "csrc/backends/hip/gfx942/amdgcn_primitives.hip.hpp"
363	// ── gate-only launch-builtin shim ────────────────────────────────────────────
364	// The free-standing AMDGCN device-compile gate (scripts/amdgcn_check.sh) stubs
365	// out <hip/hip_runtime.h>, so the kernel-launch builtins (threadIdx/blockIdx/
366	// blockDim/gridDim, __global__, __shared__) that HIP normally provides are
367	// absent. Under a real hipcc build these come from the runtime; here we model
368	// them with the AMDGCN workitem/workgroup ISA builtins so the device bodies
369	// type-check. Active ONLY on the bare gate (__AMDGCN__ && !__HIPCC__).
370	#if defined(__AMDGCN__) && !defined(__HIPCC__)
371	#ifndef GROK_GFX942_LAUNCH_SHIM_
372	#define GROK_GFX942_LAUNCH_SHIM_
373	struct GrokTidX { __device__ operator unsigned() const { return __builtin_amdgcn_workitem_id_x(); } };
374	struct GrokBidX { __device__ operator unsigned() const { return __builtin_amdgcn_workgroup_id_x(); } };
375	struct GrokBdimX{ __device__ operator unsigned() const { return __builtin_amdgcn_workgroup_size_x(); } };
376	struct GrokGdimX{ __device__ operator unsigned() const { return __builtin_amdgcn_grid_size_x()
