437	// ── device math shims (clang builtins; resolve under the bare gate AND hipcc) ─
438	__device__ __forceinline__ float dexpf(float x) { return __builtin_expf(x); }
439	__device__ __forceinline__ float dlogf(float x) { return __builtin_logf(x); }
440	__device__ __forceinline__ float dfmaxf(float a, float b) { return __builtin_fmaxf(a, b); }
441	
442	// ── bf16 <-> f32 bit codec (self-contained: the gate has no hip_bfloat16) ────
443	// bf16 is the top 16 bits of an f32. Operands flow to the MFMA wrappers as the
444	// raw `short` bit-pattern (matches amd::mfma_bf16_* which take const short[4]).
445	__device__ __forceinline__ float bf16_to_f32(short h) {
446	    unsigned u = static_cast<unsigned>(static_cast<unsigned short>(h)) << 16;
447	    return __builtin_bit_cast(float, u);
448	}
449	__device__ __forceinline__ short f32_to_bf16(float f) {
450	    unsigned u = __builtin_bit_cast(unsigned, f);
451	    unsigned lsb = (u >> 16) & 1u;
452	    u += 0x7fffu + lsb;
453	    return static_cast<short>(static_cast<unsigned short>(u >> 16));
454	}
455	
456	// ── §5.0  DPP wavefront MAX butterfly (softmax row-max) ───────────────────────
457	// The primitives header gives wave_reduce_add_dpp (SUM) but the softmax row-max
458	// needs a MAX reduction. It's the identical row-shift + row-broadcast butterfly
459	// shape with fmaxf substituted for `+` — implemented here with the same literal
460	// DPP controls (compile-time constants) via amd::dpp_mov<CTRL>. Every lane gets
461	// the wavefront max (broadcast from the top lane via readlane).
462	#define SG_DPP_MAX_F32(f, CTRL) \
463	    do { int s_ = amd::dpp_mov<CTRL>(__builtin_bit_cast(int, (f))); \
464	         (f) = dfmaxf((f), __builtin_bit_cast(float, s_)); } while (0)
465	
466	__device__ __forceinline__ float wave_reduce_max_dpp(float val) {
467	    float f = val;
468	    SG_DPP_MAX_F32(f, 0x111);  // row_shr:1
469	    SG_DPP_MAX_F32(f, 0x112);  // row_shr:2
470	    SG_DPP_MAX_F32(f, 0x114);  // row_shr:4
471	    SG_DPP_MAX_F32(f, 0x118);  // row_shr:8
472	    SG_DPP_MAX_F32(f, 0x142);  // row_bcast:15  (cross the four 16-lane rows)
473	    SG_DPP_MAX_F32(f, 0x143);  // row_bcast:31
474	    int last = __builtin_amdgcn_readlane(__builtin_bit_cast(int, f), kWave - 1);
475	    return __builtin_bit_cast(float, last);
476	}
477	
478	// ── §5.1  MFMA tiled matmul: C[MxN] = A[MxK] · Bᵀ  (row-major, K-contraction) ─
479	// REAL 16×16×16 bf16 MFMA (the §2.4 matrix-core path). One wavefront owns one
480	// 16×16 output tile; the 64 lanes hold the MFMA operand lanes the ISA defines
481	// for the 16×16×16 shape (4 bf16 / lane / 16-K step → the short[4] fragment),
482	// accumulating f32[4] across K in 16-wide steps. A is [M,K] row-major; W is
483	// [N,K] row-major (= Bᵀ already) — exactly the QKᵀ layout (S = Q·Kᵀ: A=Q[N,D],
484	// W=K[N,D], contract over D) and the O=P·V layout once V is presented as Vᵀ.
485	//
486	// Lane→fragment map for mfma_f32_16x16x16bf16 (CDNA3): lane L in [0,64) supplies
487	// A[row = L%16][k = 16*(L/16)+j] and B[col = L%16][k = 16*(L/16)+j] for j∈[0,4);
488	// acc lane L receives C[row = 4*(L/16)+r][col = L%16] in acc[r]. We load the
489	// per-lane fragments from global via streaming_load (read-once VMEM), pack to
490	// short[4], call amd::mfma_bf16_16x16x16, and interleave MFMA vs VMEM with
491	// sched_group_barrier so the matrix unit is not starved (§2.11).
492	__device__ __forceinline__ void mfma_tile_16x16(
493	    const short* __restrict__ A,   // [M, K] row-major bf16 bits
494	    const short* __restrict__ W,   // [N, K] row-major bf16 bits  (= Bᵀ)
495	    float*       __restrict__ C,   // [M, N] row-major f32
496	    int M, int N, int K,
497	    int tile_row, int tile_col)    // 16-aligned output-tile origin
498	{
499	    const int lane = static_cast<int>(threadIdx.x) % kWave;
500	    const int half = lane / 16;        // which 16-K group this lane feeds (0..3)
501	    const int idx  = lane % 16;        // row (for A) / col (for W) within the tile
502	
503	    float acc[4] = {0.f, 0.f, 0.f, 0.f};
504	
505	    const int aRow = tile_row + idx;   // A row this lane streams
506	    const int bCol = tile_col + idx;   // W row (= output col) this lane streams
507	
508	    // Contract over K in steps of 16; each lane contributes 4 bf16 of A and B.
509	    for (int k0 = 0; k0 < K; k0 += 16) {
510	        short af[4], bf[4];
511	        #pragma unroll
512	        for (int j = 0; j < 4; ++j) {
513	            int k = k0 + half * 4 + j;   // 64 lanes cover the 16 K-values ×4
514	            af[j] = (aRow < M && k < K) ? amd::streaming_load(&A[aRow * K + k]) : (short)0;
515	            bf[j] = (bCol < N && k < K) ? amd::streaming_load(&W[bCol * K + k]) : (short)0;
516	        }
517	        amd::mfma_bf16_16x16x16(acc, af, bf);
518	        amd::sched_group_barrier<0x008, 1>();   // 1 MFMA …
519	        amd::sched_group_barrier<0x100, 2>();   // … then 2 VMEM reads
520	    }
521	
522	    // Scatter the 4 accumulator rows this lane owns.
523	    #pragma unroll
524	    for (int r = 0; r < 4; ++r) {
525	        int outRow = tile_row + 4 * half + r;
526	        int outCol = tile_col + idx;
527	        if (outRow < M && outCol < N) C[outRow * N + outCol] = acc[r];
528	    }
529	}
530	
531	// Whole-matrix driver: one wavefront strides the 16×16 output-tile lattice.
532	// A:[M,K] bf16, W:[N,K] bf16 (= Bᵀ), C:[M,N] f32.
533	__device__ __forceinline__ void mfma_matmul_bf16(
534	    const short* __restrict__ A, const short* __restrict__ W,
535	    float* __restrict__ C, int M, int N, int K)
536	{
537	    const int tilesM = (M + 15) / 16;
538	    const int tilesN = (N + 15) / 16;
539	    const int nTiles = tilesM * tilesN;
540	    for (int t = 0; t < nTiles; ++t) {
541	        int tr = (t / tilesN) * 16;
542	        int tc = (t % tilesN) * 16;
543	        mfma_tile_16x16(A, W, C, M, N, K, tr, tc);
544	    }
545	}
546	
547	// ── §5.2  softmax over a score row [0,N) held by this wavefront ───────────────
548	// Stable softmax: row max via the DPP MAX butterfly (§5.0), then the exp-sum via
549	// amd::wave_reduce_add_dpp (§2.6). Each lane owns the strided score columns
550	// j = lane, lane+64, …; the in-place rescale writes the normalized weights back.
551	// Returns the log-sum-exp (m + log(sum)) for the saved softmax_lse.
552	__device__ __forceinline__ float softmax_row_inplace(
553	    float* __restrict__ scores_row, int N)
554	{
555	    const int lane = static_cast<int>(threadIdx.x) % kWave;
556	    float m = -1e30f;
557	    for (int j = lane; j < N; j += kWave) m = dfmaxf(m, scores_row[j]);
558	    m = wave_reduce_max_dpp(m);                       // §5.0 DPP max butterfly
559	    float s = 0.f;
560	    for (int j = lane; j < N; j += kWave) {
561	        float e = dexpf(scores_row[j] - m);
562	        scores_row[j] = e;
563	        s += e;
564	    }
565	    s = amd::wave_reduce_add_dpp(s);                  // §2.6 DPP sum butterfly
566	    float inv_s = 1.f / dfmaxf(s, 1e-12f);
567	    for (int j = lane; j < N; j += kWave) scores_row[j] *= inv_s;
568	    return m + dlogf(dfmaxf(s, 1e-12f));
569	}
570	
571	// ── §5.3  forward attention (one wavefront per (batch,head)) ──────────────────
572	// S = Q·Kᵀ·scale (MFMA), causal mask, row softmax (DPP), O = P·V (MFMA).
573	// Q,K,V are bf16 bit-patterns [N,D]; scores live in LDS (§2.10 budget: ≤4 KB).
574	template <int kHeadDimT, bool kCausal>
575	__device__ __forceinline__ void attention_fwd_native(
576	    const short* __restrict__ q, const short* __restrict__ k,
577	    const short* __restrict__ v, short* __restrict__ out,
578	    float* __restrict__ softmax_lse,        // [B,H,N] or nullptr
579	    float* __restrict__ scores,             // LDS scratch, N*N floats
580	    float* __restrict__ vT,                 // LDS scratch, holds Vᵀ as bf16 packed (N*D shorts) — unused on gate
581	    int bh, int N, float scale)
582	{
583	    const int lane = static_cast<int>(threadIdx.x) % kWave;
584	    const int D = kHeadDimT;
585	    const int64_t base = static_cast<int64_t>(bh) * N * D;
586	
587	    // S = Q·Kᵀ : A=q[N,D], W=k[N,D] (already Kᵀ-layout, contract over D).
588	    mfma_matmul_bf16(q + base, k + base, scores, N, N, D);
589	    amd::wait_vmcnt0();
590	
591	    // scale + causal mask, then per-row softmax (DPP reductions).
592	    for (int i = 0; i < N; ++i) {
593	        for (int j = lane; j < N; j += kWave) {
594	            float sij = scores[i * N + j] * scale;
595	            if (kCausal && j > i) sij = -1e30f;
596	            scores[i * N + j] = sij;
597	        }
598	        float lse = softmax_row_inplace(&scores[i * N], N);
599	        if (softmax_lse != nullptr && lane == 0)
600	            softmax_lse[static_cast<int64_t>(bh) * N + i] = lse;
601	    }
602	
603	    // O = P·V : P is [N,N] (row-major softmax weights), V is [N,D]. Contract over
604	    // the key index j. mfma_matmul_bf16 contracts A·Wᵀ, so feed A=P[N,N] and
605	    // W=Vᵀ[D,N] (W[d][j] = V[j][d]); we pack P and Vᵀ to bf16 in LDS first.
606	    short* Pbf = reinterpret_cast<short*>(vT);           // reuse vT scratch: N*N shorts
607	    short* Vtb = Pbf + N * N;                             // then D*N shorts for Vᵀ
608	    for (int idx = lane; idx < N * N; idx += kWave)
609	        Pbf[idx] = f32_to_bf16(scores[idx]);
610	    for (int idx = lane; idx < N * D; idx += kWave) {
611	        int j = idx / D, d = idx % D;                    // V[j][d] → Vᵀ[d][j]
612	        Vtb[d * N + j] = v[base + j * D + d];
613	    }
614	    amd::workgroup_barrier_release();
615	
616	    // O[N,D] = P[N,N] · (Vᵀ)ᵀ  → A=Pbf[N,N], W=Vtb[D,N] (= Vᵀ), contract over N.
617	    float* Of = scores;                                  // reuse scores LDS for O[N,D] f32
618	    mfma_matmul_bf16(Pbf, Vtb, Of, N, D, N);
619	    amd::wait_vmcnt0();
620	    for (int idx = lane; idx < N * D; idx += kWave)
621	        out[base + idx] = f32_to_bf16(Of[idx]);
622	}
623	
624	// ── §5.4  backward attention (recompute A from lse, MFMA dV/dA/dS/dQ/dK) ───────
625	// Mirrors the host LDS backward but with the DPP row-reduction for the softmax
626	// jacobian's per-row dot, and the MFMA tiles for the five GEMMs. The five
627	// contractions (dV=Aᵀ·dO, dA=dO·Vᵀ, dQ=dS·K, dK=dSᵀ·Q) all route through
628	// mfma_matmul_bf16; the softmax-jacobian rescale uses the DPP sum.
629	template <int kHeadDimT, bool kCausal>
630	__device__ __forceinline__ void attention_bwd_native(
631	    const short* __restrict__ grad_out, const short* __restrict__ q,
632	    const short* __restrict__ k, const short* __restrict__ v,
633	    const float* __restrict__ softmax_lse,
634	    short* __restrict__ grad_q, short* __restrict__ grad_k,
635	    short* __restrict__ grad_v,
636	    float* __restrict__ scores, float* __restrict__ dA,
637	    float* __restrict__ pack,                // bf16 packing scratch
638	    int bh, int N, float scale)
639	{
640	    const int lane = static_cast<int>(threadIdx.x) % kWave;
641	    const int D = kHeadDimT;
642	    const int64_t base = static_cast<int64_t>(bh) * N * D;
643	
644	    // Recompute attention weights A_ij = exp(scale·q_i·k_j − lse_i) via MFMA S.
645	    mfma_matmul_bf16(q + base, k + base, scores, N, N, D);
646	    amd::wait_vmcnt0();
647	    for (int i = 0; i < N; ++i) {
648	        float lse = softmax_lse[static_cast<int64_t>(bh) * N + i];
649	        for (int j = lane; j < N; j += kWave) {
650	            float a = (kCausal && j > i)
651	                    ? 0.f : dexpf(scores[i * N + j] * scale - lse);
652	            scores[i * N + j] = a;
653	        }
654	    }
655	    amd::workgroup_barrier_release();
656	
657	    short* Abf = reinterpret_cast<short*>(pack);   // N*N
658	    for (int idx = lane; idx < N * N; idx += kWave)
659	        Abf[idx] = f32_to_bf16(scores[idx]);
660	    amd::workgroup_barrier_release();
661	
662	    // dV = Aᵀ · dO : A=Aᵀ[N,N] (= columns of A), W=dOᵀ[D,N]. Build both packs.
663	    short* AtB = Abf + N * N;                       // Aᵀ
664	    short* dOt = AtB + N * N;                       // dOᵀ [D,N]
665	    for (int idx = lane; idx < N * N; idx += kWave) {
666	        int i = idx / N, j = idx % N;
667	        AtB[j * N + i] = Abf[i * N + j];
668	    }
669	    for (int idx = lane; idx < N * D; idx += kWave) {
670	        int i = idx / D, d = idx % D;
671	        dOt[d * N + i] = grad_out[base + i * D + d];
672	    }
673	    amd::workgroup_barrier_release();
674	    float* dVf = dA;                                // reuse dA LDS for dV[N,D]
675	    mfma_matmul_bf16(AtB, dOt, dVf, N, D, N);       // (Aᵀ)[N,N]·(dOᵀ)ᵀ → dV[N,D]
676	    amd::wait_vmcnt0();
677	    for (int idx = lane; idx < N * D; idx += kWave)
678	        grad_v[base + idx] = f32_to_bf16(dVf[idx]);
679	    amd::workgroup_barrier_release();
680	
681	    // dA = dO · Vᵀ : A=dO[N,D], W=V[N,D] (= already (Vᵀ)ᵀ-row layout), contract D.
682	    mfma_matmul_bf16(grad_out + base, v + base, dA, N, N, D);
683	    amd::wait_vmcnt0();
684	
685	    // softmax jacobian: dS_ij = A_ij·(dA_ij − Σ_k A_ik·dA_ik)·scale, DPP row sum.
686	    for (int i = 0; i < N; ++i) {
687	        float ds = 0.f;
688	        for (int j = lane; j < N; j += kWave)
689	            ds += scores[i * N + j] * dA[i * N + j];
690	        ds = amd::wave_reduce_add_dpp(ds);
691	        for (int j = lane; j < N; j += kWave) {
692	            float v_ds = scores[i * N + j] * (dA[i * N + j] - ds) * scale;
693	            if (kCausal && j > i) v_ds = 0.f;
694	            dA[i * N + j] = v_ds;                   // dA now holds dS
695	        }
696	    }
697	    amd::workgroup_barrier_release();
698	
699	    short* dSb = Abf;                               // repack dS into bf16 (reuse)
700	    for (int idx = lane; idx < N * N; idx += kWave)
701	        dSb[idx] = f32_to_bf16(dA[idx]);
702	    amd::workgroup_barrier_release();
703	
704	    // dQ = dS · K : A=dS[N,N], W=K[N,D] (= Kᵀ-layout), contract over j → dQ[N,D].
705	    float* dQf = dA;
706	    mfma_matmul_bf16(dSb, k + base, dQf, N, D, N);
707	    amd::wait_vmcnt0();
708	    for (int idx = lane; idx < N * D; idx += kWave)
709	        grad_q[base + idx] = f32_to_bf16(dQf[idx]);
710	    amd::workgroup_barrier_release();
711	
712	    // dK = dSᵀ · Q : A=dSᵀ[N,N], W=Q[N,D], contract over i → dK[N,D].
713	    short* dStB = AtB;
714	    for (int idx = lane; idx < N * N; idx += kWave) {
715	        int i = idx / N, j = idx % N;
716	        dStB[j * N + i] = dSb[i * N + j];
717	    }
718	    amd::workgroup_barrier_release();
719	    float* dKf = dA;
720	    mfma_matmul_bf16(dStB, q + base, dKf, N, D, N);
721	    amd::wait_vmcnt0();
722	    for (int idx = lane; idx < N * D; idx += kWave)
723	        grad_k[base + idx] = f32_to_bf16(dKf[idx]);
724	}
