732	// LDS byte budget for the forward tile (host computes this for the launch).
733	// scores[N*N] f32  +  Pbf[N*N]+Vtb[D*N] bf16 (packed) ; capped at 64 KB.
734	__device__ __forceinline__ int attention_lds_bytes_fwd(int N, int D) {
735	    int score_bytes = N * N * (int)sizeof(float);
736	    int pack_bytes  = (N * N + D * N) * (int)sizeof(short);
737	    return score_bytes + pack_bytes;
738	}
