740	// MFMA + heavy-LDS kernel: launched single-wavefront (block=64). The forward
741	// tile can consume up to the full 64 KB LDS, which caps CU occupancy to ~1
742	// wavefront regardless; so request waves_per_eu(1) — that lets the register
743	// allocator use the full VGPR file for the MFMA f32 accumulators instead of
744	// reserving for unattainable extra waves. (WS5 occupancy wire — the previously
745	// dead `waves_per_eu` config field is now a real codegen attribute.)
746	template <int kHeadDimT, bool kCausal>
747	SG_KERNEL_BOUNDS(64, 1) void attention_gfx942_fwd_mfma(
748	    const short* __restrict__ q, const short* __restrict__ k,
749	    const short* __restrict__ v, short* __restrict__ out,
750	    float* __restrict__ softmax_lse, int seq_len, float scale)
751	{
752	    extern __shared__ float lds[];
753	    const int N = seq_len, D = kHeadDimT;
754	    float* scores = lds;                       // N*N f32
755	    float* pack   = scores + N * N;            // (N*N + D*N) shorts, viewed as float scratch
756	    const int bh = static_cast<int>(blockIdx.x);
757	    attention_fwd_native<kHeadDimT, kCausal>(
758	        q, k, v, out, softmax_lse, scores, pack, bh, N, scale);
759	}
