762	SG_KERNEL_BOUNDS(64, 1) void attention_gfx942_bwd_mfma(
763	    const short* __restrict__ grad_out, const short* __restrict__ q,
764	    const short* __restrict__ k, const short* __restrict__ v,
765	    const float* __restrict__ softmax_lse,
766	    short* __restrict__ grad_q, short* __restrict__ grad_k,
767	    short* __restrict__ grad_v, int seq_len, float scale)
768	{
