684	         idx < total;
685	         idx += (int64_t)gridDim.x * blockDim.x) {
686	        int ch = static_cast<int>(idx % d_inner);
687	        int64_t fp = idx / d_inner;
688	        int b  = static_cast<int>(fp / seq_len);
689	        int t  = static_cast<int>(fp % seq_len);
690	        conv1d_silu(x_main, conv_w, conv_b, y, seq_len, d_inner, b, t, ch);
691	    }
692	}
