706	// Elementwise gated multiply (grid-stride, bandwidth-bound) → high occupancy. (WS5)
707	extern "C" SG_KERNEL_BOUNDS(256, 8) void mamba3_gfx942_gate_mul(
708	    const float* __restrict__ y_scan, const short* __restrict__ x_main,
709	    const short* __restrict__ z, const short* __restrict__ D_param,
710	    short* __restrict__ y_out, int batch, int seq_len, int d_inner)
711	{
712	    int64_t total = (int64_t)batch * seq_len * d_inner;
713	    for (int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
714	         idx < total;
715	         idx += (int64_t)gridDim.x * blockDim.x)
716	        gate_multiply(y_scan, x_main, z, D_param, y_out, idx, d_inner);
