885	// RoPE rotation on a (re, im) pair at position pos with frequency freq_idx.
886	__device__ __forceinline__ void mamba3_rope_rotate(float& re, float& im,
887	                                                    int pos, int freq_idx,
888	                                                    float theta_base = 10000.0f) {
889	    float freq  = 1.0f / powf(theta_base, static_cast<float>(2 * freq_idx) / static_cast<float>(kMamba3DState));
890	    float angle = static_cast<float>(pos) * freq;
891	    float cs, sn;
892	    sincosf(angle, &sn, &cs);
893	    float re_new = re * cs - im * sn;
894	    float im_new = re * sn + im * cs;
895	    re = re_new;
896	    im = im_new;
897	}
