900	// 64-wide wavefront reduction utilities
901	// ---------------------------------------------------------------------------
902	__device__ __forceinline__ float wavefront_reduce_sum(float val) {
903	    #pragma unroll
904	    for (int offset = kGfx942WavefrontSz / 2; offset > 0; offset >>= 1) {
905	        val += __shfl_xor(val, offset);
906	    }
907	    return val;
908	}
909	
910	__device__ __forceinline__ float wavefront_reduce_max(float val) {
911	    #pragma unroll
912	    for (int offset = kGfx942WavefrontSz / 2; offset > 0; offset >>= 1) {
913	        val = fmaxf(val, __shfl_xor(val, offset));
914	    }
915	    return val;
916	}
917	
918	// Inclusive prefix sum within a 64-wide wavefront (Hillis-Steele).
919	__device__ __forceinline__ float wavefront_inclusive_scan(float val) {
920	    #pragma unroll
921	    for (int d = 1; d < kGfx942WavefrontSz; d <<= 1) {
922	        float other = __shfl_up(val, d);
923	        if (static_cast<int>(threadIdx.x % kGfx942WavefrontSz) >= d) {
924	            val += other;
925	        }
926	    }
927	    return val;
928	}
