978	
979	// 1. Embedding lookup: token_ids [B, S] -> x [B, S, D]
980	template <typename ParamT, int SEQ_LEN, int BATCH, int VOCAB,
981	          bool TIED_EMBEDDINGS, NanPolicy NAN_POLICY>
982	__device__ __forceinline__
983	void mamba3_embed_forward(
984	    const int32_t* __restrict__ token_ids,    // [B, S]
985	    const ParamT*  __restrict__ embed_table,  // [V, D]
986	    ParamT*        __restrict__ x_out,        // [B, S, D]
987	    int d_model)
988	{
989	    const int bs = BATCH * SEQ_LEN;
990	    for (int idx = blockIdx.x * blockDim.x + threadIdx.x; idx < bs * d_model;
991	         idx += gridDim.x * blockDim.x) {
992	        int pos_in_seq = idx / d_model;
993	        int dim        = idx % d_model;
994	        int tok        = token_ids[pos_in_seq];
995	        float val      = to_float(streaming_load(&embed_table[tok * d_model + dim]));
996	        val = apply_nan_policy<NAN_POLICY>(val);
997	        x_out[idx] = from_float<ParamT>(val);
998	    }
999	}
1000	
1001	// 2. RMSNorm forward: y = x * w / rms(x)
1002	template <typename ParamT, int SEQ_LEN, int BATCH, int VOCAB,
1003	          bool TIED_EMBEDDINGS, NanPolicy NAN_POLICY>
1004	__device__ __forceinline__
1005	void mamba3_rmsnorm_forward(
1006	    const ParamT* __restrict__ x,         // [B*S, D]
1007	    const ParamT* __restrict__ weight,    // [D]
1008	    ParamT*       __restrict__ y,         // [B*S, D]
1009	    float eps,
1010	    int d_model)
1011	{
1012	    const int lane = threadIdx.x % kGfx942WavefrontSz;
1013	    const int row  = blockIdx.x * (blockDim.x / kGfx942WavefrontSz)
1014	                   + threadIdx.x / kGfx942WavefrontSz;
1015	    if (row >= BATCH * SEQ_LEN) return;
1016	
1017	    const ParamT* row_ptr = x + row * d_model;
1018	    float sum_sq = 0.0f;
1019	    for (int d = lane; d < d_model; d += kGfx942WavefrontSz) {
1020	        float v = to_float(row_ptr[d]);
1021	        sum_sq += v * v;
1022	    }
1023	    sum_sq = wavefront_reduce_sum(sum_sq);
1024	    float rms_inv = rsqrtf(sum_sq / static_cast<float>(d_model) + eps);
1025	
1026	    for (int d = lane; d < d_model; d += kGfx942WavefrontSz) {
1027	        float v = to_float(row_ptr[d]);
1028	        float w = to_float(weight[d]);
1029	        float out = v * rms_inv * w;
1030	        out = apply_nan_policy<NAN_POLICY>(out);
1031	        y[row * d_model + d] = from_float<ParamT>(out);
1032	    }
1033	}
1034	
1035	// 3. in_proj forward: xz = x @ W_in^T, xz is [B*S, 2*d_inner]
1036	//    Uses MFMA 32x32x8 bf16 tiles. One wavefront computes a 32-row output tile.
1037	template <typename ParamT, int SEQ_LEN, int BATCH, int VOCAB,
1038	          bool TIED_EMBEDDINGS, NanPolicy NAN_POLICY>
1039	__device__ __forceinline__
1040	void mamba3_in_proj_forward(
1041	    const ParamT* __restrict__ x,       // [B*S, d_model]
1042	    const ParamT* __restrict__ W,       // [2*d_inner, d_model]
1043	    ParamT*       __restrict__ xz,      // [B*S, 2*d_inner]
1044	    int d_model,
1045	    int d_inner,
1046	    float* __restrict__ smem)
1047	{
1048	    const int total_rows = BATCH * SEQ_LEN;
1049	    const int out_cols   = 2 * d_inner;
1050	    const int lane       = threadIdx.x % kGfx942WavefrontSz;
1051	
1052	    for (int row = blockIdx.x; row < total_rows; row += gridDim.x) {
1053	        for (int col = lane; col < out_cols; col += kGfx942WavefrontSz) {
1054	            float acc = 0.0f;
1055	            for (int k = 0; k < d_model; ++k) {
1056	                float a = to_float(streaming_load(&x[row * d_model + k]));
1057	                float b = to_float(streaming_load(&W[col * d_model + k]));
1058	                acc += a * b;
1059	            }
1060	            acc = apply_nan_policy<NAN_POLICY>(acc);
1061	            xz[row * out_cols + col] = from_float<ParamT>(acc);
1062	        }
1063	    }
1064	}
