1066	// 4. Conv1d forward: depthwise conv k=3, pad=1 over d_inner channels.
1067	//    64-wide wavefronts handle 64 channels at a time.
1068	template <typename ParamT, int SEQ_LEN, int BATCH, int VOCAB,
1069	          bool TIED_EMBEDDINGS, NanPolicy NAN_POLICY>
1070	__device__ __forceinline__
1071	void mamba3_conv1d_forward(
1072	    const ParamT* __restrict__ x_main,      // [B, S, d_inner]
1073	    const ParamT* __restrict__ conv_w,      // [d_inner, 1, 3]
1074	    const ParamT* __restrict__ conv_b,      // [d_inner]
1075	    ParamT*       __restrict__ y,           // [B, S, d_inner]
1076	    int d_inner)
1077	{
1078	    // Each wavefront processes 64 contiguous channels for one (batch, time) position.
1079	    const int lane  = threadIdx.x % kGfx942WavefrontSz;
1080	    const int bs    = BATCH * SEQ_LEN;
1081	    const int total = bs * d_inner;
1082	
1083	    for (int idx = blockIdx.x * blockDim.x + threadIdx.x; idx < total;
1084	         idx += gridDim.x * blockDim.x) {
1085	        int flat_pos = idx / d_inner;
1086	        int ch       = idx % d_inner;
1087	        int b        = flat_pos / SEQ_LEN;
1088	        int t        = flat_pos % SEQ_LEN;
1089	
1090	        float w0 = to_float(conv_w[ch * 3 + 0]);
1091	        float w1 = to_float(conv_w[ch * 3 + 1]);
1092	        float w2 = to_float(conv_w[ch * 3 + 2]);
1093	        float bias = to_float(conv_b[ch]);
1094	
1095	        int64_t base = static_cast<int64_t>(b) * SEQ_LEN * d_inner + ch;
1096	
1097	        float x_left  = (t > 0)           ? to_float(x_main[base + (t - 1) * d_inner]) : 0.0f;
1098	        float x_center =                    to_float(x_main[base + t       * d_inner]);
1099	        float x_right = (t < SEQ_LEN - 1) ? to_float(x_main[base + (t + 1) * d_inner]) : 0.0f;
1100	
1101	        float conv_out = w0 * x_left + w1 * x_center + w2 * x_right + bias;
1102	        float act = mamba3_silu(conv_out);
1103	        act = apply_nan_policy<NAN_POLICY>(act);
1104	        y[idx] = from_float<ParamT>(act);
1105	    }
1106	}
1107	
1108	// 5. x_proj forward: [dt_raw, B_ssm, C_ssm] = x_main @ W_x^T
1109	template <typename ParamT, int SEQ_LEN, int BATCH, int VOCAB,
1110	          bool TIED_EMBEDDINGS, NanPolicy NAN_POLICY>
1111	__device__ __forceinline__
1112	void mamba3_x_proj_forward(
1113	    const ParamT* __restrict__ x_main,    // [B*S, d_inner]
1114	    const ParamT* __restrict__ W,         // [dt_rank+2*d_state, d_inner]
1115	    ParamT*       __restrict__ dt_raw,    // [B*S, dt_rank]
1116	    ParamT*       __restrict__ B_ssm,     // [B*S, d_state]
1117	    ParamT*       __restrict__ C_ssm,     // [B*S, d_state]
1118	    int d_inner,
1119	    int dt_rank)
1120	{
1121	    const int total_rows = BATCH * SEQ_LEN;
1122	    const int out_cols   = dt_rank + 2 * kMamba3DState;
1123	    const int lane       = threadIdx.x % kGfx942WavefrontSz;
1124	
1125	    for (int row = blockIdx.x; row < total_rows; row += gridDim.x) {
1126	        for (int col = lane; col < out_cols; col += kGfx942WavefrontSz) {
1127	            float acc = 0.0f;
1128	            for (int k = 0; k < d_inner; ++k) {
1129	                float a = to_float(streaming_load(&x_main[row * d_inner + k]));
1130	                float b = to_float(streaming_load(&W[col * d_inner + k]));
1131	                acc += a * b;
1132	            }
1133	            acc = apply_nan_policy<NAN_POLICY>(acc);
1134	            if (col < dt_rank) {
1135	                dt_raw[row * dt_rank + col] = from_float<ParamT>(acc);
1136	            } else if (col < dt_rank + kMamba3DState) {
1137	                B_ssm[row * kMamba3DState + (col - dt_rank)] = from_float<ParamT>(acc);
1138	            } else {
1139	                C_ssm[row * kMamba3DState + (col - dt_rank - kMamba3DState)] = from_float<ParamT>(acc);
1140	            }
1141	        }
1142	    }
1143	}
1144	
1145	// 6. dt_proj forward: dt = softplus(dt_raw @ W_dt^T + dt_bias)
1146	template <typename ParamT, int SEQ_LEN, int BATCH, int VOCAB,
1147	          bool TIED_EMBEDDINGS, NanPolicy NAN_POLICY>
1148	__device__ __forceinline__
1149	void mamba3_dt_proj_forward(
1150	    const ParamT* __restrict__ dt_raw,      // [B*S, dt_rank]
1151	    const ParamT* __restrict__ W_dt,        // [d_inner, dt_rank]
1152	    const ParamT* __restrict__ dt_bias,     // [d_inner]
1153	    float*        __restrict__ dt_out,      // [B*S, d_inner]  (float for scan)
1154	    int d_inner,
1155	    int dt_rank)
1156	{
1157	    const int total_rows = BATCH * SEQ_LEN;
1158	    const int lane       = threadIdx.x % kGfx942WavefrontSz;
1159	
1160	    for (int row = blockIdx.x; row < total_rows; row += gridDim.x) {
1161	        for (int col = lane; col < d_inner; col += kGfx942WavefrontSz) {
1162	            float acc = to_float(dt_bias[col]);
1163	            for (int k = 0; k < dt_rank; ++k) {
1164	                float a = to_float(dt_raw[row * dt_rank + k]);
1165	                float b = to_float(W_dt[col * dt_rank + k]);
1166	                acc += a * b;
1167	            }
1168	            acc = mamba3_softplus(acc);
1169	            acc = apply_nan_policy<NAN_POLICY>(acc);
1170	            dt_out[row * d_inner + col] = acc;
1171	        }
1172	    }
1173	}
1174	
1175	// 7. SSM selective scan forward -- Blelloch parallel scan over 64-wide wavefronts.
1176	//    Processes one (batch, channel) pair per wavefront. Each lane handles ceil(S/64)
1177	//    timesteps sequentially, then wavefront-level Blelloch scan propagates prefixes.
1178	//
1179	//    Recurrence: h[t] = A_bar[t] * h[t-1] + B_bar[t] * x[t]
1180	//                y[t] = C[t]^T h[t]
1181	//    where A_bar = exp(A * dt), B_bar = dt * B.
1182	//    Paired RoPE applied to B_ssm/C_ssm state dimensions before scan.
1183	template <typename ParamT, int SEQ_LEN, int BATCH, int VOCAB,
1184	          bool TIED_EMBEDDINGS, NanPolicy NAN_POLICY>
1185	__device__ __forceinline__
1186	void mamba3_ssm_scan_forward(
1187	    const float*   __restrict__ x_main_f,  // [B, S, d_inner] (float)
1188	    const float*   __restrict__ dt,         // [B, S, d_inner]
1189	    const ParamT*  __restrict__ A_log,      // [d_inner, d_state]
1190	    const ParamT*  __restrict__ B_ssm,      // [B, S, d_state]
1191	    const ParamT*  __restrict__ C_ssm,      // [B, S, d_state]
1192	    float*         __restrict__ y_out,      // [B, S, d_inner]
1193	    float*         __restrict__ smem,       // LDS: >= SSM_SCAN_SMEM_BYTES
1194	    int d_inner)
1195	{
1196	    // One wavefront per (batch, channel). Wavefront-ID from threadblock layout.
1197	    const int lane     = threadIdx.x % kGfx942WavefrontSz;
1198	    const int wave_id  = threadIdx.x / kGfx942WavefrontSz;
1199	    const int waves_per_block = blockDim.x / kGfx942WavefrontSz;
1200	    const int global_wave = blockIdx.x * waves_per_block + wave_id;
1201	    const int total_waves = BATCH * d_inner;
1202	    if (global_wave >= total_waves) return;
1203	
1204	    const int b_idx = global_wave / d_inner;
1205	    const int ch    = global_wave % d_inner;
1206	
1207	    // LDS partition for this wavefront.
1208	    // Each wavefront gets kGfx942WavefrontSz * 2 floats for (carry_a, carry_bx) prefix storage.
1209	    float* wave_smem = smem + wave_id * kGfx942WavefrontSz * 2;
1210	
1211	    // Number of elements each lane processes sequentially.
1212	    constexpr int ELEMS_PER_LANE = (SEQ_LEN + kGfx942WavefrontSz - 1) / kGfx942WavefrontSz;
1213	
1214	    // Load A for this channel across d_state dimensions.
1215	    float A_vals[kMamba3DState];
1216	    #pragma unroll
1217	    for (int n = 0; n < kMamba3DState; ++n) {
1218	        A_vals[n] = expf(to_float(A_log[ch * kMamba3DState + n]));
1219	    }
1220	
1221	    // Per-state-dim scan. For each state dimension n, run the recurrence independently,
1222	    // accumulate contribution into y via C_ssm.
1223	    float y_accum[ELEMS_PER_LANE];
1224	    #pragma unroll
1225	    for (int e = 0; e < ELEMS_PER_LANE; ++e) {
1226	        y_accum[e] = 0.0f;
1227	    }
1228	
1229	    for (int n = 0; n < kMamba3DState; ++n) {
1230	        float A_n = A_vals[n];
1231	
1232	        // Phase 1: each lane computes a sequential segment of ELEMS_PER_LANE.
1233	        // We store the "carry" as a (multiplicative, additive) monoid pair:
1234	        //   combined_a = product of A_bar across the segment
1235	        //   combined_bx = the final h value if initial h = 0
1236	        float seg_carry_a  = 1.0f;
1237	        float seg_carry_bx = 0.0f;
1238	
1239	        float h_local[ELEMS_PER_LANE];
1240	
1241	        #pragma unroll
1242	        for (int e = 0; e < ELEMS_PER_LANE; ++e) {
1243	            int t = lane * ELEMS_PER_LANE + e;
1244	            if (t >= SEQ_LEN) {
1245	                h_local[e] = 0.0f;
1246	                continue;
1247	            }
1248	
1249	            float dt_val = dt[b_idx * SEQ_LEN * d_inner + t * d_inner + ch];
1250	            float A_bar  = expf(logf(A_n) * dt_val);  // A_n^dt  =  exp(log(A_n)*dt)
1251	            float x_val  = x_main_f[b_idx * SEQ_LEN * d_inner + t * d_inner + ch];
1252	
1253	            // B with RoPE: paired rotation on (B[n], B[n^1]) where n^1 flips LSB.
1254	            float b_raw = to_float(B_ssm[b_idx * SEQ_LEN * kMamba3DState + t * kMamba3DState + n]);
1255	            float b_pair = to_float(B_ssm[b_idx * SEQ_LEN * kMamba3DState + t * kMamba3DState + (n ^ 1)]);
1256	            float b_re = b_raw, b_im = b_pair;
1257	            mamba3_rope_rotate(b_re, b_im, t, n / 2);
1258	            float b_val = b_re; // take real part after rotation
1259	
1260	            float B_bar = dt_val * b_val;
1261	
1262	            // Recurrence within segment: h = A_bar * h_prev + B_bar * x
1263	            seg_carry_bx = A_bar * seg_carry_bx + B_bar * x_val;
1264	            seg_carry_a  = A_bar * seg_carry_a;
1265	            h_local[e]   = seg_carry_bx;
1266	        }
1267	
1268	        // Phase 2: Blelloch (work-efficient) parallel prefix scan of carry monoid
1269	        // across 64 lanes. Monoid composition: (a2, bx2) o (a1, bx1) = (a2*a1, a2*bx1 + bx2)
1270	        // Store per-lane carries to LDS.
1271	        wave_smem[lane * 2 + 0] = seg_carry_a;
1272	        wave_smem[lane * 2 + 1] = seg_carry_bx;
1273	        __builtin_amdgcn_fence(__ATOMIC_RELEASE, "workgroup");
1274	        __builtin_amdgcn_s_barrier();
1275	
1276	        // Up-sweep (reduce) in LDS -- log2(64) = 6 steps.
1277	        #pragma unroll
1278	        for (int stride = 1; stride < kGfx942WavefrontSz; stride <<= 1) {
1279	            int idx = (lane + 1) * (stride << 1) - 1;
1280	            if (idx < kGfx942WavefrontSz) {
1281	                int left = idx - stride;
1282	                float a_left  = wave_smem[left * 2 + 0];
1283	                float bx_left = wave_smem[left * 2 + 1];
1284	                float a_right = wave_smem[idx * 2 + 0];
1285	                float bx_right = wave_smem[idx * 2 + 1];
1286	                // Compose: right o left
1287	                wave_smem[idx * 2 + 0] = a_right * a_left;
1288	                wave_smem[idx * 2 + 1] = a_right * bx_left + bx_right;
1289	            }
1290	            __builtin_amdgcn_fence(__ATOMIC_ACQ_REL, "workgroup");
1291	            __builtin_amdgcn_s_barrier();
1292	        }
1293	
1294	        // Clear the last element (identity for exclusive scan).
1295	        if (lane == 0) {
1296	            wave_smem[(kGfx942WavefrontSz - 1) * 2 + 0] = 1.0f;
1297	            wave_smem[(kGfx942WavefrontSz - 1) * 2 + 1] = 0.0f;
1298	        }
1299	        __builtin_amdgcn_fence(__ATOMIC_RELEASE, "workgroup");
1300	        __builtin_amdgcn_s_barrier();
1301	
1302	        // Down-sweep.
1303	        #pragma unroll
1304	        for (int stride = kGfx942WavefrontSz / 2; stride >= 1; stride >>= 1) {
1305	            int idx = (lane + 1) * (stride << 1) - 1;
1306	            if (idx < kGfx942WavefrontSz) {
1307	                int left = idx - stride;
1308	                float a_tmp  = wave_smem[left * 2 + 0];
1309	                float bx_tmp = wave_smem[left * 2 + 1];
1310	                float a_right  = wave_smem[idx * 2 + 0];
1311	                float bx_right = wave_smem[idx * 2 + 1];
1312	                // Left gets old right (exclusive prefix up to here).
1313	                wave_smem[left * 2 + 0] = a_right;
1314	                wave_smem[left * 2 + 1] = bx_right;
1315	                // Right = right o left_old.
1316	                wave_smem[idx * 2 + 0] = a_right * a_tmp;
1317	                wave_smem[idx * 2 + 1] = a_right * bx_tmp + bx_right;
1318	            }
1319	            __builtin_amdgcn_fence(__ATOMIC_ACQ_REL, "workgroup");
1320	            __builtin_amdgcn_s_barrier();
1321	        }
1322	
1323	        // Phase 3: each lane reads its exclusive prefix and adjusts local h values.
1324	        float prefix_a  = wave_smem[lane * 2 + 0];
1325	        float prefix_bx = wave_smem[lane * 2 + 1];
1326	        __builtin_amdgcn_s_barrier();
1327	
1328	        #pragma unroll
1329	        for (int e = 0; e < ELEMS_PER_LANE; ++e) {
1330	            int t = lane * ELEMS_PER_LANE + e;
1331	            if (t >= SEQ_LEN) continue;
1332	
1333	            // h_global[t] = prefix_a * h_local[e] + prefix_bx  (for first element in segment)
1334	            // But h_local already contains the sequential scan from h=0 within the segment.
1335	            // The correct adjustment: h_adjusted = prefix_a * h_local[e] + prefix_bx
1336	            float h_final = prefix_a * h_local[e] + prefix_bx;
1337	
1338	            // C with RoPE.
1339	            float c_raw  = to_float(C_ssm[b_idx * SEQ_LEN * kMamba3DState + t * kMamba3DState + n]);
1340	            float c_pair = to_float(C_ssm[b_idx * SEQ_LEN * kMamba3DState + t * kMamba3DState + (n ^ 1)]);
1341	            float c_re = c_raw, c_im = c_pair;
1342	            mamba3_rope_rotate(c_re, c_im, t, n / 2);
1343	
1344	            y_accum[e] += c_re * h_final;
1345	        }
1346	    } // end for each state dim n
1347	
1348	    // Write y_out.
1349	    #pragma unroll
1350	    for (int e = 0; e < ELEMS_PER_LANE; ++e) {
1351	        int t = lane * ELEMS_PER_LANE + e;
1352	        if (t >= SEQ_LEN) continue;
1353	        float val = apply_nan_policy<NAN_POLICY>(y_accum[e]);
1354	        y_out[b_idx * SEQ_LEN * d_inner + t * d_inner + ch] = val;
1355	    }
1356	}
1357	
1358	// 8. Gate multiply: y = (y_scan + x_main * D) * SiLU(z)
1359	template <typename ParamT, int SEQ_LEN, int BATCH, int VOCAB,
1360	          bool TIED_EMBEDDINGS, NanPolicy NAN_POLICY>
1361	__device__ __forceinline__
1362	void mamba3_gate_multiply_forward(
1363	    const float*  __restrict__ y_scan,    // [B, S, d_inner]
1364	    const ParamT* __restrict__ x_main,    // [B, S, d_inner]
1365	    const ParamT* __restrict__ z,         // [B, S, d_inner]
1366	    const ParamT* __restrict__ D_param,   // [d_inner]
1367	    ParamT*       __restrict__ y_out,     // [B, S, d_inner]
1368	    int d_inner)
1369	{
1370	    const int total = BATCH * SEQ_LEN * d_inner;
1371	    for (int idx = blockIdx.x * blockDim.x + threadIdx.x; idx < total;
1372	         idx += gridDim.x * blockDim.x) {
1373	        int ch = idx % d_inner;
1374	        float y_s  = y_scan[idx];
1375	        float x_m  = to_float(x_main[idx]);
1376	        float z_v  = to_float(z[idx]);
1377	        float D_v  = to_float(D_param[ch]);
1378	
1379	        float gated = (y_s + x_m * D_v) * mamba3_silu(z_v);

1380	        gated = apply_nan_policy<NAN_POLICY>(gated);
1381	        y_out[idx] = from_float<ParamT>(gated);
1382	    }
1383	}
1384	
1385	// 9. out_proj forward: y = y_gated @ W_out^T
1386	template <typename ParamT, int SEQ_LEN, int BATCH, int VOCAB,
1387	          bool TIED_EMBEDDINGS, NanPolicy NAN_POLICY>
1388	__device__ __forceinline__
1389	void mamba3_out_proj_forward(
1390	    const ParamT* __restrict__ y_gated,   // [B*S, d_inner]
1391	    const ParamT* __restrict__ W_out,     // [d_model, d_inner]
1392	    ParamT*       __restrict__ y_out,     // [B*S, d_model]
1393	    int d_model,
1394	    int d_inner,
1395	    float* __restrict__ smem)
1396	{
1397	    const int total_rows = BATCH * SEQ_LEN;
1398	    const int lane       = threadIdx.x % kGfx942WavefrontSz;
1399	
1400	    for (int row = blockIdx.x; row < total_rows; row += gridDim.x) {
1401	        for (int col = lane; col < d_model; col += kGfx942WavefrontSz) {
1402	            float acc = 0.0f;
1403	            for (int k = 0; k < d_inner; ++k) {
1404	                float a = to_float(streaming_load(&y_gated[row * d_inner + k]));
1405	                float b = to_float(streaming_load(&W_out[col * d_inner + k]));
1406	                acc += a * b;
1407	            }
1408	            acc = apply_nan_policy<NAN_POLICY>(acc);
1409	            y_out[row * d_model + col] = from_float<ParamT>(acc);
1410	        }
1411	    }
1412	}
1413	
1414	// 10. Residual add: y = out_proj_result + residual
1415	template <typename ParamT, int SEQ_LEN, int BATCH, int VOCAB,
1416	          bool TIED_EMBEDDINGS, NanPolicy NAN_POLICY>
1417	__device__ __forceinline__
1418	void mamba3_residual_add_forward(
1419	    const ParamT* __restrict__ proj_out,   // [B*S, D]
1420	    const ParamT* __restrict__ residual,   // [B*S, D]
1421	    ParamT*       __restrict__ y,          // [B*S, D]
1422	    int d_model)
1423	{
1424	    const int total = BATCH * SEQ_LEN * d_model;
1425	    for (int idx = blockIdx.x * blockDim.x + threadIdx.x; idx < total;
1426	         idx += gridDim.x * blockDim.x) {
1427	        float p = to_float(proj_out[idx]);
1428	        float r = to_float(residual[idx]);
1429	        float val = apply_nan_policy<NAN_POLICY>(p + r);
1430	        y[idx] = from_float<ParamT>(val);
1431	    }
1432	}
1433	
1434	// 11. LM head: logits = hidden @ embed^T (tied) or hidden @ lm_weight^T
1435	template <typename ParamT, int SEQ_LEN, int BATCH, int VOCAB,
1436	          bool TIED_EMBEDDINGS, NanPolicy NAN_POLICY>
1437	__device__ __forceinline__
1438	void mamba3_lm_head_forward(
1439	    const ParamT* __restrict__ hidden,         // [B*S, d_model]
1440	    const ParamT* __restrict__ lm_weight,      // [V, d_model] (or embed_table if tied)
1441	    const ParamT* __restrict__ embed_table,    // [V, d_model]
1442	    float*        __restrict__ logits,         // [B*S, V]
1443	    int d_model)
1444	{
1445	    const ParamT* W = TIED_EMBEDDINGS ? embed_table : lm_weight;
1446	    const int total_rows = BATCH * SEQ_LEN;
1447	    const int lane       = threadIdx.x % kGfx942WavefrontSz;
1448	
1449	    for (int row = blockIdx.x; row < total_rows; row += gridDim.x) {
1450	        for (int v = lane; v < VOCAB; v += kGfx942WavefrontSz) {
1451	            float acc = 0.0f;
1452	            for (int k = 0; k < d_model; ++k) {
1453	                float h = to_float(hidden[row * d_model + k]);
1454	                float w = to_float(streaming_load(&W[v * d_model + k]));
1455	                acc += h * w;
1456	            }
1457	            acc = apply_nan_policy<NAN_POLICY>(acc);
1458	            logits[row * VOCAB + v] = acc;
1459	        }
1460	    }
1461	}
