1463	// ---------------------------------------------------------------------------
1464	// Backward layer functions
1465	// ---------------------------------------------------------------------------
1466	
1467	// Backward: RMSNorm
1468	template <typename ParamT, int SEQ_LEN, int BATCH, int VOCAB,
1469	          bool TIED_EMBEDDINGS, NanPolicy NAN_POLICY>
1470	__device__ __forceinline__
1471	void mamba3_rmsnorm_backward(
1472	    const ParamT* __restrict__ dy,         // [B*S, D]
1473	    const ParamT* __restrict__ x,          // [B*S, D]
1474	    const ParamT* __restrict__ weight,     // [D]
1475	    ParamT*       __restrict__ dx,         // [B*S, D]
1476	    float*        __restrict__ dweight,    // [D] atomicAdd accumulation
1477	    float eps,
1478	    int d_model)
1479	{
1480	    const int lane = threadIdx.x % kGfx942WavefrontSz;
1481	    const int row  = blockIdx.x * (blockDim.x / kGfx942WavefrontSz)
1482	                   + threadIdx.x / kGfx942WavefrontSz;
1483	    if (row >= BATCH * SEQ_LEN) return;
1484	
1485	    const ParamT* x_row  = x  + row * d_model;
1486	    const ParamT* dy_row = dy + row * d_model;
1487	
1488	    float sum_sq = 0.0f;
1489	    for (int d = lane; d < d_model; d += kGfx942WavefrontSz) {
1490	        float v = to_float(x_row[d]);
1491	        sum_sq += v * v;
1492	    }
1493	    sum_sq = wavefront_reduce_sum(sum_sq);
1494	    float var_inv = rsqrtf(sum_sq / static_cast<float>(d_model) + eps);
1495	
1496	    float dot = 0.0f;
1497	    for (int d = lane; d < d_model; d += kGfx942WavefrontSz) {
1498	        float v  = to_float(x_row[d]);
1499	        float g  = to_float(dy_row[d]);
1500	        float w  = to_float(weight[d]);
1501	        dot += g * w * v;
1502	    }
1503	    dot = wavefront_reduce_sum(dot);
1504	    float coeff = dot * var_inv * var_inv * var_inv / static_cast<float>(d_model);
1505	
1506	    for (int d = lane; d < d_model; d += kGfx942WavefrontSz) {
1507	        float v  = to_float(x_row[d]);
1508	        float g  = to_float(dy_row[d]);
1509	        float w  = to_float(weight[d]);
1510	        float dx_val = (g * w * var_inv - coeff * v);
1511	        dx_val = apply_nan_policy<NAN_POLICY>(dx_val);
1512	        dx[row * d_model + d] = from_float<ParamT>(dx_val);
1513	        atomicAdd(&dweight[d], g * v * var_inv);
1514	    }
1515	}
1516	
1517	// Backward: residual add -- trivially passes gradient through
1518	template <typename ParamT, int SEQ_LEN, int BATCH, int VOCAB,
1519	          bool TIED_EMBEDDINGS, NanPolicy NAN_POLICY>
1520	__device__ __forceinline__
1521	void mamba3_residual_add_backward(
1522	    const ParamT* __restrict__ dy,
1523	    ParamT*       __restrict__ d_proj,
1524	    ParamT*       __restrict__ d_residual,
1525	    int d_model)
1526	{
1527	    const int total = BATCH * SEQ_LEN * d_model;
1528	    for (int idx = blockIdx.x * blockDim.x + threadIdx.x; idx < total;
1529	         idx += gridDim.x * blockDim.x) {
1530	        float g = to_float(dy[idx]);
1531	        g = apply_nan_policy<NAN_POLICY>(g);
1532	        d_proj[idx]     = from_float<ParamT>(g);
1533	        d_residual[idx] = from_float<ParamT>(g);
1534	    }
1535	}
