1537	// Backward: out_proj -- dY_gated = dY @ W_out, dW_out = dY^T @ Y_gated
1538	template <typename ParamT, int SEQ_LEN, int BATCH, int VOCAB,
1539	          bool TIED_EMBEDDINGS, NanPolicy NAN_POLICY>
1540	__device__ __forceinline__
1541	void mamba3_out_proj_backward(
1542	    const ParamT* __restrict__ dy,           // [B*S, d_model]
1543	    const ParamT* __restrict__ y_gated,      // [B*S, d_inner]
1544	    const ParamT* __restrict__ W_out,        // [d_model, d_inner]
1545	    ParamT*       __restrict__ dy_gated,     // [B*S, d_inner]
1546	    float*        __restrict__ dW_out,       // [d_model, d_inner]
1547	    int d_model,
1548	    int d_inner)
1549	{
1550	    const int total_rows = BATCH * SEQ_LEN;
1551	    const int lane       = threadIdx.x % kGfx942WavefrontSz;
1552	
1553	    // dy_gated = dy @ W_out  (W_out is [d_model, d_inner])
1554	    for (int row = blockIdx.x; row < total_rows; row += gridDim.x) {
1555	        for (int col = lane; col < d_inner; col += kGfx942WavefrontSz) {
1556	            float acc = 0.0f;
1557	            for (int k = 0; k < d_model; ++k) {
1558	                float d_val = to_float(dy[row * d_model + k]);
1559	                float w_val = to_float(W_out[k * d_inner + col]);
1560	                acc += d_val * w_val;
1561	            }
1562	            acc = apply_nan_policy<NAN_POLICY>(acc);
1563	            dy_gated[row * d_inner + col] = from_float<ParamT>(acc);
1564	        }
1565	        // dW_out += dy[row]^T @ y_gated[row] (rank-1 outer product)
1566	        for (int r = lane; r < d_model; r += kGfx942WavefrontSz) {
1567	            float d_val = to_float(dy[row * d_model + r]);
1568	            for (int c = 0; c < d_inner; ++c) {
1569	                float y_val = to_float(y_gated[row * d_inner + c]);
1570	                atomicAdd(&dW_out[r * d_inner + c], d_val * y_val);
1571	            }
1572	        }
1573	    }
1574	}
