1576	// Backward: gate multiply -- d(y_scan), d(x_main via D), d(z)
1577	template <typename ParamT, int SEQ_LEN, int BATCH, int VOCAB,
1578	          bool TIED_EMBEDDINGS, NanPolicy NAN_POLICY>
1579	__device__ __forceinline__
1580	void mamba3_gate_multiply_backward(
1581	    const ParamT* __restrict__ dy,         // [B, S, d_inner]
1582	    const float*  __restrict__ y_scan,     // [B, S, d_inner]
1583	    const ParamT* __restrict__ x_main,     // [B, S, d_inner]
1584	    const ParamT* __restrict__ z,          // [B, S, d_inner]
1585	    const ParamT* __restrict__ D_param,    // [d_inner]
1586	    float*        __restrict__ dy_scan,    // [B, S, d_inner]
1587	    ParamT*       __restrict__ dx_main_D,  // [B, S, d_inner] contribution from D
1588	    ParamT*       __restrict__ dz,         // [B, S, d_inner]
1589	    float*        __restrict__ dD,         // [d_inner]
1590	    int d_inner)
1591	{
1592	    const int total = BATCH * SEQ_LEN * d_inner;
1593	    for (int idx = blockIdx.x * blockDim.x + threadIdx.x; idx < total;
1594	         idx += gridDim.x * blockDim.x) {
1595	        int ch   = idx % d_inner;
1596	        float dout = to_float(dy[idx]);
1597	        float ys   = y_scan[idx];
1598	        float xm   = to_float(x_main[idx]);
1599	        float zv   = to_float(z[idx]);
1600	        float Dv   = to_float(D_param[ch]);
1601	
1602	        float sig_z  = 1.0f / (1.0f + expf(-zv));
1603	        float silu_z = zv * sig_z;
1604	        float inner  = ys + xm * Dv;
1605	
1606	        // d/d(y_scan) = dout * silu(z)
1607	        float dys = apply_nan_policy<NAN_POLICY>(dout * silu_z);
1608	        dy_scan[idx] = dys;
1609	
1610	        // d/d(x_main via D) = dout * D * silu(z)
1611	        float dxD = apply_nan_policy<NAN_POLICY>(dout * Dv * silu_z);
1612	        dx_main_D[idx] = from_float<ParamT>(dxD);
1613	
1614	        // d/d(z) = dout * inner * d(silu)/dz, where d(silu)/dz = sig + z*sig*(1-sig)
1615	        float dsilu = sig_z + zv * sig_z * (1.0f - sig_z);
1616	        float dzv = apply_nan_policy<NAN_POLICY>(dout * inner * dsilu);
1617	        dz[idx] = from_float<ParamT>(dzv);
1618	
1619	        // d/d(D) -- accumulate
1620	        atomicAdd(&dD[ch], dout * xm * silu_z);
1621	    }
1622	}
