1624	// Backward: SSM scan (reverse-time parallel scan).
1625	// Uses the same Blelloch structure as forward but sweeps in reverse.
1626	template <typename ParamT, int SEQ_LEN, int BATCH, int VOCAB,
1627	          bool TIED_EMBEDDINGS, NanPolicy NAN_POLICY>
1628	__device__ __forceinline__
1629	void mamba3_ssm_scan_backward(
1630	    const float*  __restrict__ dy_scan,    // [B, S, d_inner]
1631	    const float*  __restrict__ x_main_f,   // [B, S, d_inner]
1632	    const float*  __restrict__ dt,         // [B, S, d_inner]
1633	    const ParamT* __restrict__ A_log,      // [d_inner, d_state]
1634	    const ParamT* __restrict__ B_ssm,      // [B, S, d_state]
1635	    const ParamT* __restrict__ C_ssm,      // [B, S, d_state]
1636	    float*        __restrict__ dx_out,     // [B, S, d_inner] (add to existing)
1637	    float*        __restrict__ ddt_out,    // [B, S, d_inner]
1638	    float*        __restrict__ dA_log,     // [d_inner, d_state]
1639	    float*        __restrict__ dB_ssm,     // [B, S, d_state]
1640	    float*        __restrict__ dC_ssm,     // [B, S, d_state]
1641	    float*        __restrict__ smem,
1642	    int d_inner)
1643	{
1644	    const int lane     = threadIdx.x % kGfx942WavefrontSz;
1645	    const int wave_id  = threadIdx.x / kGfx942WavefrontSz;
1646	    const int waves_per_block = blockDim.x / kGfx942WavefrontSz;
1647	    const int global_wave = blockIdx.x * waves_per_block + wave_id;
1648	    const int total_waves = BATCH * d_inner;
1649	    if (global_wave >= total_waves) return;
1650	
1651	    const int b_idx = global_wave / d_inner;
1652	    const int ch    = global_wave % d_inner;
1653	    float* wave_smem = smem + wave_id * kGfx942WavefrontSz * 2;
1654	
1655	    constexpr int ELEMS_PER_LANE = (SEQ_LEN + kGfx942WavefrontSz - 1) / kGfx942WavefrontSz;
1656	
1657	    float A_vals[kMamba3DState];
1658	    #pragma unroll
1659	    for (int n = 0; n < kMamba3DState; ++n) {
1660	        A_vals[n] = expf(to_float(A_log[ch * kMamba3DState + n]));
1661	    }
1662	
1663	    // For each state dim, run reverse-time adjoint scan.
1664	    for (int n = 0; n < kMamba3DState; ++n) {
1665	        float A_n = A_vals[n];
1666	
1667	        // Reverse sequential pass within each lane's segment.
1668	        float seg_carry_a  = 1.0f;
1669	        float seg_carry_bx = 0.0f;
1670	        float dh_local[ELEMS_PER_LANE];
1671	
1672	        #pragma unroll
1673	        for (int e = ELEMS_PER_LANE - 1; e >= 0; --e) {
1674	            // Reverse mapping: lane processes timesteps in reverse order.
1675	            int t = (kGfx942WavefrontSz - 1 - lane) * ELEMS_PER_LANE + (ELEMS_PER_LANE - 1 - e);
1676	            if (t >= SEQ_LEN || t < 0) {
1677	                dh_local[e] = 0.0f;
1678	                continue;
1679	            }
1680	
1681	            float dt_val = dt[b_idx * SEQ_LEN * d_inner + t * d_inner + ch];
1682	            float A_bar  = expf(logf(A_n) * dt_val);
1683	
1684	            float c_raw  = to_float(C_ssm[b_idx * SEQ_LEN * kMamba3DState + t * kMamba3DState + n]);
1685	            float c_pair = to_float(C_ssm[b_idx * SEQ_LEN * kMamba3DState + t * kMamba3DState + (n ^ 1)]);
1686	            float c_re = c_raw, c_im = c_pair;
1687	            mamba3_rope_rotate(c_re, c_im, t, n / 2);
1688	
1689	            float dy_val = dy_scan[b_idx * SEQ_LEN * d_inner + t * d_inner + ch];
1690	
1691	            // dh[t] = C[t] * dy[t] + A_bar[t+1] * dh[t+1]  (reverse recurrence)
1692	            seg_carry_bx = A_bar * seg_carry_bx + c_re * dy_val;
1693	            seg_carry_a  = A_bar * seg_carry_a;
1694	            dh_local[e]  = seg_carry_bx;
1695	        }
1696	
1697	        // Blelloch scan on reverse carries (same monoid structure, reversed lane order).
1698	        wave_smem[lane * 2 + 0] = seg_carry_a;
1699	        wave_smem[lane * 2 + 1] = seg_carry_bx;
1700	        __builtin_amdgcn_fence(__ATOMIC_RELEASE, "workgroup");
1701	        __builtin_amdgcn_s_barrier();
1702	
1703	        #pragma unroll
1704	        for (int stride = 1; stride < kGfx942WavefrontSz; stride <<= 1) {
1705	            int idx = (lane + 1) * (stride << 1) - 1;
1706	            if (idx < kGfx942WavefrontSz) {
1707	                int left = idx - stride;
1708	                float a_l = wave_smem[left * 2 + 0], bx_l = wave_smem[left * 2 + 1];
1709	                float a_r = wave_smem[idx  * 2 + 0], bx_r = wave_smem[idx  * 2 + 1];
1710	                wave_smem[idx * 2 + 0] = a_r * a_l;
1711	                wave_smem[idx * 2 + 1] = a_r * bx_l + bx_r;
1712	            }
1713	            __builtin_amdgcn_fence(__ATOMIC_ACQ_REL, "workgroup");
1714	            __builtin_amdgcn_s_barrier();
1715	        }
1716	
1717	        if (lane == 0) {
1718	            wave_smem[(kGfx942WavefrontSz - 1) * 2 + 0] = 1.0f;
1719	            wave_smem[(kGfx942WavefrontSz - 1) * 2 + 1] = 0.0f;
1720	        }
1721	        __builtin_amdgcn_fence(__ATOMIC_RELEASE, "workgroup");
1722	        __builtin_amdgcn_s_barrier();
1723	
1724	        #pragma unroll
1725	        for (int stride = kGfx942WavefrontSz / 2; stride >= 1; stride >>= 1) {
1726	            int idx = (lane + 1) * (stride << 1) - 1;
1727	            if (idx < kGfx942WavefrontSz) {
1728	                int left = idx - stride;
1729	                float a_tmp = wave_smem[left * 2 + 0], bx_tmp = wave_smem[left * 2 + 1];
1730	                float a_r   = wave_smem[idx  * 2 + 0], bx_r   = wave_smem[idx  * 2 + 1];
1731	                wave_smem[left * 2 + 0] = a_r;
1732	                wave_smem[left * 2 + 1] = bx_r;
1733	                wave_smem[idx * 2 + 0] = a_r * a_tmp;
1734	                wave_smem[idx * 2 + 1] = a_r * bx_tmp + bx_r;
1735	            }
1736	            __builtin_amdgcn_fence(__ATOMIC_ACQ_REL, "workgroup");
1737	            __builtin_amdgcn_s_barrier();
1738	        }
1739	
1740	        float prefix_a  = wave_smem[lane * 2 + 0];
1741	        float prefix_bx = wave_smem[lane * 2 + 1];
1742	        __builtin_amdgcn_s_barrier();
1743	
1744	        // Apply prefix and accumulate parameter gradients.
1745	        #pragma unroll
1746	        for (int e = ELEMS_PER_LANE - 1; e >= 0; --e) {
1747	            int t = (kGfx942WavefrontSz - 1 - lane) * ELEMS_PER_LANE + (ELEMS_PER_LANE - 1 - e);
1748	            if (t >= SEQ_LEN || t < 0) continue;
1749	
1750	            float dh_final = prefix_a * dh_local[e] + prefix_bx;
1751	
1752	            float dt_val = dt[b_idx * SEQ_LEN * d_inner + t * d_inner + ch];
1753	            float x_val  = x_main_f[b_idx * SEQ_LEN * d_inner + t * d_inner + ch];
1754	
1755	            float b_raw  = to_float(B_ssm[b_idx * SEQ_LEN * kMamba3DState + t * kMamba3DState + n]);
1756	            float b_pair = to_float(B_ssm[b_idx * SEQ_LEN * kMamba3DState + t * kMamba3DState + (n ^ 1)]);
1757	            float b_re = b_raw, b_im = b_pair;
1758	            mamba3_rope_rotate(b_re, b_im, t, n / 2);
1759	
1760	            // dx += dh * dt * B_rope * (for this state dim)
1761	            atomicAdd(&dx_out[b_idx * SEQ_LEN * d_inner + t * d_inner + ch],
1762	                      dh_final * dt_val * b_re);
1763	
1764	            // ddt += dh * (B_rope * x + A_log_val * h_prev)  -- simplified accumulation
1765	            atomicAdd(&ddt_out[b_idx * SEQ_LEN * d_inner + t * d_inner + ch],
1766	                      dh_final * b_re * x_val);
1767	
1768	            // dB_ssm (before RoPE -- chain rule through rotation)
1769	            atomicAdd(&dB_ssm[b_idx * SEQ_LEN * kMamba3DState + t * kMamba3DState + n],
1770	                      dh_final * dt_val * x_val);
1771	
1772	            // dA_log
1773	            atomicAdd(&dA_log[ch * kMamba3DState + n],
1774	                      dh_final * dt_val * A_vals[n]);
1775	        }
1776	    }
1777	}
