1834	// Backward: in_proj -- dx = dxz @ W_in, dW_in = dxz^T @ x
1835	template <typename ParamT, int SEQ_LEN, int BATCH, int VOCAB,
1836	          bool TIED_EMBEDDINGS, NanPolicy NAN_POLICY>
1837	__device__ __forceinline__
1838	void mamba3_in_proj_backward(
1839	    const ParamT* __restrict__ dxz,       // [B*S, 2*d_inner]
1840	    const ParamT* __restrict__ x,         // [B*S, d_model]
1841	    const ParamT* __restrict__ W_in,      // [2*d_inner, d_model]
1842	    ParamT*       __restrict__ dx,        // [B*S, d_model]
1843	    float*        __restrict__ dW_in,     // [2*d_inner, d_model]
1844	    int d_model,
1845	    int d_inner)
1846	{
1847	    const int total_rows = BATCH * SEQ_LEN;
1848	    const int in_cols    = 2 * d_inner;
1849	    const int lane       = threadIdx.x % kGfx942WavefrontSz;
1850	
1851	    for (int row = blockIdx.x; row < total_rows; row += gridDim.x) {
1852	        // dx[row] = dxz[row] @ W_in
1853	        for (int col = lane; col < d_model; col += kGfx942WavefrontSz) {
1854	            float acc = 0.0f;
1855	            for (int k = 0; k < in_cols; ++k) {
1856	                float d_val = to_float(dxz[row * in_cols + k]);
1857	                float w_val = to_float(W_in[k * d_model + col]);
1858	                acc += d_val * w_val;
1859	            }
1860	            acc = apply_nan_policy<NAN_POLICY>(acc);
1861	            dx[row * d_model + col] = from_float<ParamT>(acc);
1862	        }
1863	        // dW_in accumulation
1864	        for (int r = lane; r < in_cols; r += kGfx942WavefrontSz) {
1865	            float dxz_val = to_float(dxz[row * in_cols + r]);
1866	            for (int c = 0; c < d_model; ++c) {
1867	                float x_val = to_float(x[row * d_model + c]);
1868	                atomicAdd(&dW_in[r * d_model + c], dxz_val * x_val);
1869	            }
1870	        }
1871	    }
1872	}
