1874	// Backward: embed (scatter gradient into embedding table)
1875	template <typename ParamT, int SEQ_LEN, int BATCH, int VOCAB,
1876	          bool TIED_EMBEDDINGS, NanPolicy NAN_POLICY>
1877	__device__ __forceinline__
1878	void mamba3_embed_backward(
1879	    const ParamT*  __restrict__ dx,            // [B*S, d_model]
1880	    const int32_t* __restrict__ token_ids,     // [B*S]
1881	    float*         __restrict__ d_embed_table,  // [V, d_model]
1882	    int d_model)
1883	{
1884	    const int bs = BATCH * SEQ_LEN;
1885	    for (int idx = blockIdx.x * blockDim.x + threadIdx.x; idx < bs * d_model;
1886	         idx += gridDim.x * blockDim.x) {
1887	        int pos = idx / d_model;
1888	        int dim = idx % d_model;
1889	        int tok = token_ids[pos];
1890	        float g = to_float(dx[idx]);
1891	        g = apply_nan_policy<NAN_POLICY>(g);
1892	        atomicAdd(&d_embed_table[tok * d_model + dim], g);
1893	    }
1894	}
