1896	// Backward: LM head
1897	template <typename ParamT, int SEQ_LEN, int BATCH, int VOCAB,
1898	          bool TIED_EMBEDDINGS, NanPolicy NAN_POLICY>
1899	__device__ __forceinline__
1900	void mamba3_lm_head_backward(
1901	    const float*  __restrict__ dlogits,       // [B*S, V]
1902	    const ParamT* __restrict__ hidden,        // [B*S, d_model]
1903	    const ParamT* __restrict__ lm_weight,     // [V, d_model]
1904	    const ParamT* __restrict__ embed_table,   // [V, d_model]
1905	    ParamT*       __restrict__ dhidden,       // [B*S, d_model]
1906	    float*        __restrict__ dW,            // [V, d_model]
1907	    int d_model)
1908	{
1909	    const ParamT* W = TIED_EMBEDDINGS ? embed_table : lm_weight;
1910	    const int total_rows = BATCH * SEQ_LEN;
1911	    const int lane       = threadIdx.x % kGfx942WavefrontSz;
1912	
1913	    for (int row = blockIdx.x; row < total_rows; row += gridDim.x) {
1914	        // dhidden = dlogits @ W
1915	        for (int col = lane; col < d_model; col += kGfx942WavefrontSz) {
1916	            float acc = 0.0f;
1917	            for (int v = 0; v < VOCAB; ++v) {
1918	                float dl = dlogits[row * VOCAB + v];
1919	                float w  = to_float(W[v * d_model + col]);
1920	                acc += dl * w;
1921	            }
1922	            acc = apply_nan_policy<NAN_POLICY>(acc);
1923	            dhidden[row * d_model + col] = from_float<ParamT>(acc);
1924	        }
1925	        // dW += dlogits^T @ hidden
1926	        for (int v = lane; v < VOCAB; v += kGfx942WavefrontSz) {
1927	            float dl = dlogits[row * VOCAB + v];
1928	            for (int c = 0; c < d_model; ++c) {
1929	                float h = to_float(hidden[row * d_model + c]);
1930	                atomicAdd(&dW[v * d_model + c], dl * h);
1931	            }
1932	        }
1933	    }
1934	}
