1936	// Backward: x_proj
1937	template <typename ParamT, int SEQ_LEN, int BATCH, int VOCAB,
1938	          bool TIED_EMBEDDINGS, NanPolicy NAN_POLICY>
1939	__device__ __forceinline__
1940	void mamba3_x_proj_backward(
1941	    const ParamT* __restrict__ ddt_raw,    // [B*S, dt_rank]
1942	    const float*  __restrict__ dB_ssm,     // [B*S, d_state]
1943	    const float*  __restrict__ dC_ssm,     // [B*S, d_state]
1944	    const ParamT* __restrict__ x_main,     // [B*S, d_inner]
1945	    const ParamT* __restrict__ W_x,        // [dt_rank+2*d_state, d_inner]
1946	    ParamT*       __restrict__ dx_main,    // [B*S, d_inner]
1947	    float*        __restrict__ dW_x,       // [dt_rank+2*d_state, d_inner]
1948	    int d_inner,
1949	    int dt_rank)
1950	{
1951	    const int total_rows = BATCH * SEQ_LEN;
1952	    const int out_cols   = dt_rank + 2 * kMamba3DState;
1953	    const int lane       = threadIdx.x % kGfx942WavefrontSz;
1954	
1955	    for (int row = blockIdx.x; row < total_rows; row += gridDim.x) {
1956	        // dx_main[row] = concat(ddt_raw, dB, dC)[row] @ W_x
1957	        for (int col = lane; col < d_inner; col += kGfx942WavefrontSz) {
1958	            float acc = 0.0f;
1959	            for (int k = 0; k < out_cols; ++k) {
1960	                float dval;
1961	                if (k < dt_rank) {
1962	                    dval = to_float(ddt_raw[row * dt_rank + k]);
1963	                } else if (k < dt_rank + kMamba3DState) {
1964	                    dval = dB_ssm[row * kMamba3DState + (k - dt_rank)];
1965	                } else {
1966	                    dval = dC_ssm[row * kMamba3DState + (k - dt_rank - kMamba3DState)];
1967	                }
1968	                float w = to_float(W_x[k * d_inner + col]);
1969	                acc += dval * w;
1970	            }
1971	            acc = apply_nan_policy<NAN_POLICY>(acc);
1972	            // Accumulate into dx_main (may already have contributions from gate backward).
1973	            float prev = to_float(dx_main[row * d_inner + col]);
1974	            dx_main[row * d_inner + col] = from_float<ParamT>(prev + acc);
1975	        }
1976	    }
1977	}
