1979	// Backward: dt_proj
1980	template <typename ParamT, int SEQ_LEN, int BATCH, int VOCAB,
1981	          bool TIED_EMBEDDINGS, NanPolicy NAN_POLICY>
1982	__device__ __forceinline__
1983	void mamba3_dt_proj_backward(
1984	    const float*  __restrict__ ddt,         // [B*S, d_inner] (from scan backward)
1985	    const ParamT* __restrict__ dt_raw,      // [B*S, dt_rank]
1986	    const ParamT* __restrict__ W_dt,        // [d_inner, dt_rank]
1987	    const ParamT* __restrict__ dt_bias,     // [d_inner]
1988	    ParamT*       __restrict__ ddt_raw,     // [B*S, dt_rank]
1989	    float*        __restrict__ dW_dt,       // [d_inner, dt_rank]
1990	    float*        __restrict__ ddt_bias,    // [d_inner]
1991	    int d_inner,
1992	    int dt_rank)
1993	{
1994	    const int total_rows = BATCH * SEQ_LEN;
1995	    const int lane       = threadIdx.x % kGfx942WavefrontSz;
1996	
1997	    for (int row = blockIdx.x; row < total_rows; row += gridDim.x) {
1998	        // softplus backward: d/dx softplus(x) = sigmoid(x)
1999	        // Then chain through the linear dt_proj.
2000	        for (int col = lane; col < d_inner; col += kGfx942WavefrontSz) {
2001	            // Recompute pre-softplus value.
2002	            float pre_sp = to_float(dt_bias[col]);
2003	            for (int k = 0; k < dt_rank; ++k) {
2004	                pre_sp += to_float(dt_raw[row * dt_rank + k]) * to_float(W_dt[col * dt_rank + k]);
2005	            }
2006	            float sig = 1.0f / (1.0f + expf(-pre_sp));
2007	            float ddt_val = ddt[row * d_inner + col] * sig;
2008	
2009	            atomicAdd(&ddt_bias[col], ddt_val);
2010	
2011	            for (int k = 0; k < dt_rank; ++k) {
2012	                float dt_r = to_float(dt_raw[row * dt_rank + k]);
2013	                atomicAdd(&dW_dt[col * dt_rank + k], ddt_val * dt_r);
2014	                // ddt_raw accumulation via transpose.
2015	                float w = to_float(W_dt[col * dt_rank + k]);
2016	                atomicAdd(reinterpret_cast<float*>(&ddt_raw[row * dt_rank + k]),
2017	                          ddt_val * w);
2018	            }
2019	        }
2020	    }
2021	}
