1575	void launch_moe_adam_step(
1576	    std::vector<torch::Tensor>& params,
1577	    std::vector<torch::Tensor>& exp_avgs,
1578	    std::vector<torch::Tensor>& exp_avg_sqs,
1579	    std::vector<torch::Tensor>& grads,
1580	    float lr, float beta1, float beta2, float eps, float wd,
1581	    float bc1, float bc2
1582	) {
1583	    for (size_t i = 0; i < params.size(); i++) {
1584	        if (!grads[i].defined() || grads[i].numel() == 0) continue;
1585	        auto& p = params[i];
1586	        auto& g = grads[i];
1587	        auto& m = exp_avgs[i];
1588	        auto& v = exp_avg_sqs[i];
1589	
1590	#if defined(__HIPCC__)
1591	        // LIVE device path: the §5.ADAM f32x4-vectorized AdamW apply fuses the m/v
1592	        // EMAs and the bias-corrected decoupled-WD apply into ONE launch (128-bit
1593	        // dwordx4 access). float param/grad only; other dtypes fall back to ATen.
1594	        if (p.scalar_type() == torch::kFloat32 && g.scalar_type() == torch::kFloat32 &&
1595	            p.is_contiguous() && g.is_contiguous() &&
1596	            m.is_contiguous() && v.is_contiguous()) {
1597	            const int64_t n = static_cast<int64_t>(p.numel());  // Stage 1: 64-bit
1598	            hipStream_t stream = at::hip::getCurrentHIPStream();
1599	            dim3 grid(static_cast<unsigned>(
1600	                std::min<int64_t>(1024, (n + 255) / 256))), block(256);
1601	            hipLaunchKernelGGL((native::sg2_gfx942_adam_apply<float, float>),
1602	                               grid, block, 0, stream,
1603	                               p.data_ptr<float>(), m.data_ptr<float>(),
1604	                               v.data_ptr<float>(), g.data_ptr<float>(),
1605	                               lr, beta1, beta2, eps, wd, bc1, bc2, n);
1606	            SG_HIP_LAUNCH_CHECK(stream);  // mirror sm_90 SG_LAUNCH_CHECK
1607	            continue;
1608	        }
1609	#endif
1610	        prim::ema_update_inplace(m, g, beta1);
1611	        prim::ema_sq_update_inplace(v, g, beta2);
1612	        prim::adam_apply_inplace(p, m, v, lr, bc1, bc2, eps, wd);
1613	    }
1614	}
