1626	//  __HIPCC__) the `#else` is ATen tensor ops (which reach rocBLAS / rocPRIM
1627	//  internally), semantically mirroring the sm_90 CUDA path. The
1628	//  compute_load_balance_loss / apply_frequency_scaling controllers + the
1629	//  dynamic_expert_{load,fwd,bwd} bmm experts stay ATen (small / not MFMA-bound).
1630	//
1631	//  Reachability (verified): Python's _moe_step calls count_expert_activations,
1632	//  compute_load_balance_loss, apply_frequency_scaling, filter_active_params,
1633	//  scatter_results. dynamic_expert_{load,fwd,bwd} and scan_compacted are
1634	//  exported for ABI but not currently called; still implemented correctly.
1635	//  moe_scan_compacted is VESTIGIAL (Mamba-era; SG2's mixer is now CSA/HCA).
1636	// ═══════════════════════════════════════════════════════════════════════
1637	
1638	// ── (1) Expert-activation histogram ──
1639	//  expert_counts[e] += #rows with gate_logits[:,e] > threshold (int32).
1640	void moe_count_expert_activations(
1641	    torch::Tensor gate_logits, torch::Tensor expert_counts,
1642	    float threshold, int N, int num_experts) {
1643	    if (N == 0 || num_experts == 0) return;
1644	#if defined(__HIPCC__)
1645	    // DEVICE path: per-expert histogram kernel (DPP-reduced column tallies).
1646	    {
1647	        auto gl = gate_logits.to(torch::kFloat32).contiguous();
1648	        auto counts_u = torch::zeros({num_experts},
1649	            torch::TensorOptions().dtype(torch::kInt32).device(gate_logits.device()));
1650	        hipStream_t st = at::hip::getCurrentHIPStream();
1651	        dim3 grid(1, (unsigned)num_experts);   // gridDim.y selects the expert col
1652	        hipLaunchKernelGGL(native::moe_expert_histogram_kernel,
1653	            grid, dim3(64), 0, st,
1654	            gl.data_ptr<float>(),
1655	            reinterpret_cast<unsigned*>(counts_u.data_ptr<int>()),
1656	            threshold, N, num_experts);
1657	        SG_HIP_LAUNCH_CHECK(st);  // mirror sm_90 SG_LAUNCH_CHECK
1658	        expert_counts.copy_(counts_u);
1659	        return;
1660	    }
1661	#else
1662	    auto gl = gate_logits.to(torch::kFloat32);
1663	    auto counts = (gl > threshold).sum(/*dim=*/0).to(torch::kInt32);  // [E]
1664	    expert_counts.copy_(counts);
1665	#endif
1666	}
1667	
1668	// ── (2) Switch-Transformer load-balance auxiliary loss ──
1669	//  loss = E * Σ_e f_e * P_e ; f_e = counts[e]/N ; P_e = mean_t softmax(gl)[t,e].
1670	torch::Tensor moe_compute_load_balance_loss(
1671	    torch::Tensor expert_counts, torch::Tensor gate_logits,
1672	    int N, int num_experts) {
1673	    auto opts = torch::TensorOptions()
1674	        .dtype(torch::kFloat32).device(gate_logits.device());
1675	    if (N == 0 || num_experts == 0) return torch::zeros({}, opts);
1676	    auto gl = gate_logits.to(torch::kFloat32);
1677	    auto P = torch::softmax(gl, /*dim=*/1).mean(/*dim=*/0);              // [E]
1678	    auto f = expert_counts.to(torch::kFloat32) / static_cast<double>(N); // [E]
1679	    return static_cast<double>(num_experts) * (f * P).sum();
1680	}
1681	
1682	// ── (3) Frequency-inverse per-expert LR scaling ──
1683	//  freq_e = (counts[e]+s)/(total+s*E) ; scale_e = clamp((1/E)/freq_e, lo, hi).
1684	void moe_apply_frequency_scaling(
1685	    torch::Tensor expert_counts, torch::Tensor lr_scale,
1686	    int num_experts, int total_activations,
1687	    float min_scale, float max_scale, float smoothing) {
1688	    if (num_experts == 0) return;
1689	    const double denom = static_cast<double>(total_activations)
1690	                       + static_cast<double>(smoothing) * num_experts;
1691	    const double uniform = 1.0 / static_cast<double>(num_experts);
1692	    auto freq = (expert_counts.to(torch::kFloat32) + smoothing) / denom;  // [E]
1693	    auto scale = torch::clamp(uniform / freq, min_scale, max_scale);      // [E]
1694	    lr_scale.copy_(scale.to(torch::kFloat32));
1695	}
1696	
1697	// ── (4) Stream-compaction of active-expert parameters ──
1698	//  Keep index i iff expert_active[param_to_expert[i]] != 0. We build a boolean
1699	//  mask and use it to gather the kept elements (deterministic ascending order,
1700	//  unlike the sm_90 atomic compaction — both satisfy the (out->i) scatter
1701	//  contract). compact_count[0] = #kept; outputs filled in [0, kept).
1702	void moe_filter_active_params(
1703	    torch::Tensor params, torch::Tensor grads,
1704	    torch::Tensor state_m, torch::Tensor state_v,
1705	    torch::Tensor param_to_expert, torch::Tensor expert_active,
1706	    torch::Tensor compact_params, torch::Tensor compact_grads,
1707	    torch::Tensor compact_state_m, torch::Tensor compact_state_v,
1708	    torch::Tensor scatter_indices, torch::Tensor compact_count,
1709	    int total_params) {
1710	    if (total_params == 0) {
1711	        compact_count.zero_();
1712	        return;
1713	    }
1714	    torch::Tensor idx;
1715	#if defined(__HIPCC__)
1716	    // DEVICE path: ballot-compaction filter kernel builds the kept-index list via
1717	    // a wave-exclusive scan + atomic cursor (rocPRIM-shaped, the §5.1 kernel).
1718	    {
1719	        auto p2e_i = param_to_expert.to(torch::kInt32).contiguous();
1720	        auto act_i = expert_active.to(torch::kInt32).contiguous();
1721	        auto out_idx = torch::empty({total_params},
1722	            torch::TensorOptions().dtype(torch::kInt32).device(params.device()));
1723	        auto cursor = torch::zeros({1},
1724	            torch::TensorOptions().dtype(torch::kInt32).device(params.device()));
1725	        hipStream_t st = at::hip::getCurrentHIPStream();
1726	        const int threads = 256;
1727	        const int blocks = (total_params + threads - 1) / threads;
1728	        hipLaunchKernelGGL(native::moe_filter_active_kernel,
1729	            dim3(blocks), dim3(threads), 0, st,
1730	            p2e_i.data_ptr<int>(), act_i.data_ptr<int>(),
1731	            out_idx.data_ptr<int>(),
1732	            reinterpret_cast<unsigned*>(cursor.data_ptr<int>()),
1733	            total_params);
1734	        SG_HIP_LAUNCH_CHECK(st);  // mirror sm_90 SG_LAUNCH_CHECK
1735	        const int64_t Kd = cursor.to(torch::kCPU).item<int>();
1736	        // The device filter emits indices in cursor (atomic) order; sort to the
1737	        // deterministic ascending order the ATen contract guarantees.
1738	        idx = std::get<0>(out_idx.narrow(0, 0, Kd).to(torch::kLong).sort());
1739	    }
1740	#else
1741	    auto p2e = param_to_expert.to(torch::kLong);                  // [P]
1742	    auto active = expert_active.to(torch::kBool);                 // [E]
1743	    auto keep = active.index_select(0, p2e);                      // [P] bool
1744	    idx = torch::nonzero(keep).reshape(-1);                       // [K] long
1745	#endif
1746	    const int64_t K = idx.numel();
1747	    compact_count.fill_(static_cast<int>(K));
1748	    if (K == 0) return;
1749	    compact_params.narrow(0, 0, K).copy_(params.index_select(0, idx));
1750	    compact_grads.narrow(0, 0, K).copy_(grads.index_select(0, idx));
1751	    compact_state_m.narrow(0, 0, K).copy_(state_m.index_select(0, idx));
1752	    compact_state_v.narrow(0, 0, K).copy_(state_v.index_select(0, idx));
1753	    scatter_indices.narrow(0, 0, K).copy_(idx.to(torch::kInt32));
1754	}
1755	
1756	// ── (5) Scatter compacted results back to dense storage ──
1757	//  params[scatter_indices[j]] = compact_params[j], etc. (inverse of (4)).
1758	void moe_scatter_results(
1759	    torch::Tensor compact_params,
1760	    torch::Tensor compact_state_m, torch::Tensor compact_state_v,
1761	    torch::Tensor scatter_indices,
1762	    torch::Tensor params,
1763	    torch::Tensor state_m, torch::Tensor state_v,
1764	    int compact_N) {
1765	    if (compact_N == 0) return;
1766	#if defined(__HIPCC__)
1767	    // DEVICE path: §5.2 scatter kernel (1:1 row map → accumulate=0 streaming
1768	    // store) for each of params / state_m / state_v (row_stride=1).
1769	    {
1770	        auto idx_i = scatter_indices.narrow(0, 0, compact_N).to(torch::kInt32).contiguous();
1771	        hipStream_t st = at::hip::getCurrentHIPStream();
1772	        const int threads = 256;
1773	        const int blocks = (compact_N + threads - 1) / threads;
1774	        auto launch = [&](torch::Tensor& dst, const torch::Tensor& src) {
1775	            auto s = src.narrow(0, 0, compact_N).to(torch::kFloat32).contiguous();
1776	            auto d = dst.to(torch::kFloat32).contiguous();
1777	            hipLaunchKernelGGL(native::moe_scatter_results_kernel,
1778	                dim3(blocks), dim3(threads), 0, st,
1779	                s.data_ptr<float>(), idx_i.data_ptr<int>(), d.data_ptr<float>(),
1780	                compact_N, /*row_stride=*/1, /*accumulate=*/0);
1781	            SG_HIP_LAUNCH_CHECK(st);  // mirror sm_90 SG_LAUNCH_CHECK
1782	            dst.copy_(d.to(dst.dtype()));
1783	        };
1784	        launch(params, compact_params);
1785	        launch(state_m, compact_state_m);
1786	        launch(state_v, compact_state_v);
1787	        return;
1788	    }
1789	#else
1790	    auto idx = scatter_indices.narrow(0, 0, compact_N).to(torch::kLong);
1791	    params.index_copy_(0, idx, compact_params.narrow(0, 0, compact_N));
1792	    state_m.index_copy_(0, idx, compact_state_m.narrow(0, 0, compact_N));
1793	    state_v.index_copy_(0, idx, compact_state_v.narrow(0, 0, compact_N));
1794	#endif
1795	}
