1797	// ── (6) Masked gather of active expert weights ──
1798	//  Pack the slices of expert_{w1,b1,w2,b2} where active_mask[e]!=0, in
1799	//  ascending expert order, into the smem_* buffers.
1800	void moe_dynamic_expert_load(
1801	    torch::Tensor expert_w1, torch::Tensor expert_b1,
1802	    torch::Tensor expert_w2, torch::Tensor expert_b2,
1803	    torch::Tensor active_mask,
1804	    torch::Tensor smem_w1, torch::Tensor smem_b1,
1805	    torch::Tensor smem_w2, torch::Tensor smem_b2) {
1806	    auto idx = torch::nonzero(active_mask.reshape(-1) != 0).reshape(-1);  // [A]
1807	    const int64_t A = idx.numel();
1808	    if (A == 0) return;
1809	    smem_w1.narrow(0, 0, A).copy_(expert_w1.index_select(0, idx));
1810	    smem_w2.narrow(0, 0, A).copy_(expert_w2.index_select(0, idx));
1811	    smem_b1.narrow(0, 0, A).copy_(expert_b1.index_select(0, idx));
1812	    smem_b2.narrow(0, 0, A).copy_(expert_b2.index_select(0, idx));
1813	}
1814	
1815	// ── (7) Per-token expert MLP forward ──
1816	//  output[t] = rw[t] * (W2_e @ relu(W1_e @ input[t] + b1_e) + b2_e).
1817	//  Shapes: input [N,d_in]; expert_w1 [E,hidden,d_in]; expert_w2 [E,d_out,hidden].
1818	//  Vectorized with batched bmm over per-token gathered expert weights.
1819	torch::Tensor moe_dynamic_expert_fwd(
1820	    torch::Tensor input, torch::Tensor expert_indices,
1821	    torch::Tensor routing_weights,
1822	    torch::Tensor expert_w1, torch::Tensor expert_b1,
1823	    torch::Tensor expert_w2, torch::Tensor expert_b2,
1824	    torch::Tensor output) {
1825	    const int64_t N = input.size(0);
1826	    if (N == 0) return output;
1827	    auto x   = input.to(torch::kFloat32);                       // [N,d_in]
1828	    auto idx = expert_indices.to(torch::kLong);                 // [N]
1829	    auto rw  = routing_weights.to(torch::kFloat32).reshape({N, 1});
1830	    auto W1  = expert_w1.to(torch::kFloat32).index_select(0, idx);  // [N,H,d_in]
1831	    auto b1  = expert_b1.to(torch::kFloat32).index_select(0, idx);  // [N,H]
1832	    auto W2  = expert_w2.to(torch::kFloat32).index_select(0, idx);  // [N,d_out,H]
1833	    auto b2  = expert_b2.to(torch::kFloat32).index_select(0, idx);  // [N,d_out]
1834	    // h = relu(W1 @ x + b1)  -> [N,H]
1835	    auto h = torch::relu(
1836	        torch::bmm(W1, x.unsqueeze(2)).squeeze(2) + b1);           // [N,H]
1837	    auto y = torch::bmm(W2, h.unsqueeze(2)).squeeze(2) + b2;       // [N,d_out]
1838	    output.copy_(rw * y);
1839	    return output;
1840	}
1841	
1842	// ── (8) Per-token expert MLP backward (full VJP) ──
1843	//  dy = rw * d_output ; db2_e += dy ; dW2_e += dy⊗h ; dh = W2ᵀdy ;
1844	//  dz1 = dh ⊙ [z1>0] ; dW1_e += dz1⊗x ; db1_e += dz1 ; d_input = W1ᵀ dz1.
1845	//  Expert-weight grads accumulated via index_add_ (multiple tokens per expert).
1846	void moe_dynamic_expert_bwd(
1847	    torch::Tensor d_output, torch::Tensor input,
1848	    torch::Tensor expert_indices, torch::Tensor routing_weights,
1849	    torch::Tensor expert_w1, torch::Tensor expert_b1,
1850	    torch::Tensor expert_w2, torch::Tensor expert_b2,
1851	    torch::Tensor d_input, torch::Tensor d_expert_w1,
1852	    torch::Tensor d_expert_b1, torch::Tensor d_expert_w2,
1853	    torch::Tensor d_expert_b2) {
1854	    const int64_t N = input.size(0);
1855	    if (N == 0) return;
1856	    auto x   = input.to(torch::kFloat32);                          // [N,d_in]
1857	    auto dout = d_output.to(torch::kFloat32);                      // [N,d_out]
1858	    auto idx = expert_indices.to(torch::kLong);                    // [N]
1859	    auto rw  = routing_weights.to(torch::kFloat32).reshape({N, 1});
1860	    auto W1g = expert_w1.to(torch::kFloat32).index_select(0, idx); // [N,H,d_in]
1861	    auto b1g = expert_b1.to(torch::kFloat32).index_select(0, idx); // [N,H]
1862	    auto W2g = expert_w2.to(torch::kFloat32).index_select(0, idx); // [N,d_out,H]
1863	
1864	    // Recompute forward activations.
1865	    auto z1 = torch::bmm(W1g, x.unsqueeze(2)).squeeze(2) + b1g;    // [N,H]
1866	    auto relu_mask = (z1 > 0).to(torch::kFloat32);                 // [N,H]
1867	    auto h = z1 * relu_mask;                                       // [N,H]
1868	
1869	    auto dy = rw * dout;                                           // [N,d_out]
1870	    // dW2 = dy ⊗ h : [N,d_out,H] ; db2 = dy ; dh = W2ᵀ dy.
1871	    auto dW2 = torch::bmm(dy.unsqueeze(2), h.unsqueeze(1));        // [N,d_out,H]
1872	    auto db2 = dy;                                                 // [N,d_out]
1873	    auto dh = torch::bmm(W2g.transpose(1, 2), dy.unsqueeze(2)).squeeze(2); // [N,H]
1874	    auto dz1 = dh * relu_mask;                                     // [N,H]
1875	    auto dW1 = torch::bmm(dz1.unsqueeze(2), x.unsqueeze(1));       // [N,H,d_in]
1876	    auto db1 = dz1;                                                // [N,H]
1877	    auto dx = torch::bmm(W1g.transpose(1, 2), dz1.unsqueeze(2)).squeeze(2); // [N,d_in]
1878	    d_input.copy_(dx);
1879	
1880	    // Scatter-accumulate per-expert grads. Tensor::index_add_ on a GPU device is
1881	    // documented run-to-run NONDETERMINISTIC (it lowers to floating-point atomic
1882	    // scatter, completion-order-dependent). The sm_90 twin (commit 5cb32b8) made
1883	    // the per-token atomic path NON-default and selects a DETERMINISTIC
1884	    // one-block-per-expert (atomic-free, fixed-order) reduction by default,
1885	    // gating the fast atomic variant behind SG2_ATOMIC_MOE_BWD=1; HIP atomics
1886	    // have the same nondeterminism, so mirror that default here.
1887	    const char* atomic_env = std::getenv("SG2_ATOMIC_MOE_BWD");
1888	    const bool use_atomic = (atomic_env != nullptr && atomic_env[0] == '1');
1889	    if (use_atomic) {
1890	        // Fast (nondeterministic) atomic scatter — opt-in for speed comparisons.
1891	        d_expert_w1.index_add_(0, idx, dW1);
1892	        d_expert_b1.index_add_(0, idx, db1);
1893	        d_expert_w2.index_add_(0, idx, dW2);
1894	        d_expert_b2.index_add_(0, idx, db2);
1895	        return;
1896	    }
1897	    // Deterministic default: per-expert reduction via a dense one-hot contraction
1898	    // (onehot[E,N] @ dgrad[N,...]). A matmul/sum reduction has a FIXED summation
1899	    // order, so the result is reproducible run-to-run (atomic-free), matching the
1900	    // sm_90 deterministic one-block-per-expert default. Mathematically identical
1901	    // to index_add_ (Σ over the tokens routed to each expert), only the reduction
1902	    // order differs. onehot[e,n] = 1 iff token n routed to expert e.
1903	    const int64_t E = expert_w1.size(0);
1904	    auto onehot = torch::zeros({E, N}, x.options());                  // [E,N]
1905	    onehot.scatter_(0, idx.reshape({1, N}), 1.0f);
1906	    // W1/b1: [E,H,d_in] += onehot @ dW1[N,H,d_in] (flatten trailing dims to mm).
1907	    d_expert_w1.add_(torch::mm(onehot, dW1.reshape({N, -1}))
1908	                         .reshape(d_expert_w1.sizes()));
1909	    d_expert_b1.add_(torch::mm(onehot, db1.reshape({N, -1}))
1910	                         .reshape(d_expert_b1.sizes()));
1911	    d_expert_w2.add_(torch::mm(onehot, dW2.reshape({N, -1}))
1912	                         .reshape(d_expert_w2.sizes()));
1913	    d_expert_b2.add_(torch::mm(onehot, db2.reshape({N, -1}))
1914	                         .reshape(d_expert_b2.sizes()));
1915	}
1916	
1917	// ── (9) Compacted selective scan — VESTIGIAL ──
1918	//  Mamba-era discretized SSM recurrence; SG2's mixer is now CSA/HCA and Python
1919	//  NEVER calls this. Kept linkable + numerically sound for ABI stability.
1920	//    A = -exp(A_log) ; A_bar = exp(dt*A) ; h_t = A_bar*h_{t-1} + (dt*B_t)*x_t ;
1921	//    y_t = Σ_s C_t[s]*h_t[d,s] + D[d]*x_t[d].
1922	//  Layout: compact_x/dt [Nc,d_inner]; compact_B/C [Nc,d_state];
1923	//          A_log [d_inner,d_state]; D_param [d_inner];
1924	//          initial/final_state [d_inner,d_state]; scan_output [Nc,d_inner].
1925	void moe_scan_compacted(
1926	    torch::Tensor compact_x, torch::Tensor compact_dt,
1927	    torch::Tensor compact_B, torch::Tensor compact_C,
1928	    torch::Tensor A_log, torch::Tensor D_param,
1929	    torch::Tensor rope_freq,
1930	    torch::Tensor scan_output, torch::Tensor final_state,
1931	    torch::Tensor initial_state,
1932	    int compact_N, int d_inner, int d_state) {
1933	    (void)rope_freq;  // vestigial positional arg (Mamba-era), intentionally unused.
1934	    if (compact_N == 0 || d_inner == 0) return;
1935	    auto x  = compact_x.to(torch::kFloat32);     // [Nc,d_inner]
1936	    auto dt = compact_dt.to(torch::kFloat32);    // [Nc,d_inner]
1937	    auto B  = compact_B.to(torch::kFloat32);     // [Nc,d_state]
1938	    auto C  = compact_C.to(torch::kFloat32);     // [Nc,d_state]
1939	    auto A  = -torch::exp(A_log.to(torch::kFloat32));  // [d_inner,d_state]
1940	    auto opts = torch::TensorOptions()
1941	        .dtype(torch::kFloat32).device(x.device());
1942	    auto h = (initial_state.defined() && initial_state.numel() > 0)
1943	           ? initial_state.to(torch::kFloat32).clone()
1944	           : torch::zeros({d_inner, d_state}, opts);     // [d_inner,d_state]
1945	    auto Dvec = (D_param.defined() && D_param.numel() > 0)
1946	              ? D_param.to(torch::kFloat32)
1947	              : torch::zeros({d_inner}, opts);            // [d_inner]
1948	    for (int t = 0; t < compact_N; ++t) {
1949	        auto xt = x[t].reshape({d_inner, 1});             // [d_inner,1]
1950	        auto dtt = dt[t].reshape({d_inner, 1});           // [d_inner,1]
1951	        auto Bt = B[t].reshape({1, d_state});             // [1,d_state]
1952	        auto Ct = C[t].reshape({1, d_state});             // [1,d_state]
1953	        auto A_bar = torch::exp(dtt * A);                 // [d_inner,d_state]
1954	        h = A_bar * h + (dtt * Bt) * xt;                  // [d_inner,d_state]
1955	        auto y = (h * Ct).sum(/*dim=*/1) + Dvec * x[t];   // [d_inner]
1956	        scan_output[t].copy_(y);
1957	    }
1958	    if (final_state.defined() && final_state.numel() > 0)
1959	        final_state.copy_(h);
1960	}
