2073	// SG2 fixed geometry (CDNA3 wavefront width = 64; grokking shapes).
2074	static constexpr int kWave    = 64;   // == amd::kWave
2075	static constexpr int kHeadDim = 4;    // grokking head_dim (d_model=8 / heads=2)
