2077	// ── device math shims (clang builtins; resolve under the bare gate AND hipcc) ─
2078	__device__ __forceinline__ float dexpf(float x)  { return __builtin_expf(x); }
2079	__device__ __forceinline__ float dlogf(float x)  { return __builtin_logf(x); }

2080	__device__ __forceinline__ float dtanhf(float x) { return __builtin_tanhf(x); }
2081	__device__ __forceinline__ float dfmaxf(float a, float b) { return __builtin_fmaxf(a, b); }
2082	__device__ __forceinline__ float dsigmoidf(float x) { return 1.f / (1.f + dexpf(-x)); }
2083	__device__ __forceinline__ float dreluf(float x) { return x > 0.f ? x : 0.f; }
2084	
2085	// ── bf16 <-> f32 bit codec (self-contained: the gate has no hip_bfloat16) ────
2086	// bf16 is the top 16 bits of an f32. Operands flow to the MFMA wrappers as the
2087	// raw `short` bit-pattern (matches amd::mfma_bf16_* which take const short[4]).
2088	__device__ __forceinline__ float bf16_to_f32(short h) {
2089	    unsigned u = static_cast<unsigned>(static_cast<unsigned short>(h)) << 16;
2090	    return __builtin_bit_cast(float, u);
2091	}
2092	__device__ __forceinline__ short f32_to_bf16(float f) {
2093	    unsigned u = __builtin_bit_cast(unsigned, f);
2094	    unsigned lsb = (u >> 16) & 1u;
2095	    u += 0x7fffu + lsb;
2096	    return static_cast<short>(static_cast<unsigned short>(u >> 16));
2097	}
2098	
2099	// ── §5.0  DPP wavefront MAX butterfly (softmax row-max) ───────────────────────
2100	// The primitives header gives wave_reduce_add_dpp (SUM) but the softmax row-max
2101	// needs a MAX reduction — identical row-shift + row-broadcast butterfly shape
2102	// with fmaxf substituted for `+`, built (as attention_gfx942 did) on the same
2103	// literal DPP controls via amd::dpp_mov<CTRL>. Every lane gets the wave max.
2104	#define SG2_DPP_MAX_F32(f, CTRL) \
2105	    do { int s_ = amd::dpp_mov<CTRL>(__builtin_bit_cast(int, (f))); \
2106	         (f) = dfmaxf((f), __builtin_bit_cast(float, s_)); } while (0)
2107	
2108	__device__ __forceinline__ float wave_reduce_max_dpp(float val) {
2109	    float f = val;
2110	    SG2_DPP_MAX_F32(f, 0x111);  // row_shr:1
2111	    SG2_DPP_MAX_F32(f, 0x112);  // row_shr:2
2112	    SG2_DPP_MAX_F32(f, 0x114);  // row_shr:4
2113	    SG2_DPP_MAX_F32(f, 0x118);  // row_shr:8
2114	    SG2_DPP_MAX_F32(f, 0x142);  // row_bcast:15  (cross the four 16-lane rows)
2115	    SG2_DPP_MAX_F32(f, 0x143);  // row_bcast:31
2116	    int last = __builtin_amdgcn_readlane(__builtin_bit_cast(int, f), kWave - 1);
2117	    return __builtin_bit_cast(float, last);
2118	}
2119	
2120	// ── §5.1  MFMA tiled matmul: C[MxN] = A[MxK] · Wᵀ  (row-major, K-contraction) ─
2121	// REAL 16×16×16 bf16 MFMA (the §2.4 matrix-core path). One wavefront owns one
2122	// 16×16 output tile; the 64 lanes hold the operand-lane map the ISA defines for
2123	// the 16×16×16 shape (4 bf16 / lane / 16-K step → the short[4] fragment),
2124	// accumulating f32[4] across K in 16-wide steps. A is [M,K] row-major; W is
2125	// [N,K] row-major (= Bᵀ already) — exactly the QKᵀ layout (S=Q·Kᵀ: A=Q[N,D],
2126	// W=K[N,D]) and the O=P·V layout with V presented as Vᵀ. Per-lane fragments are
2127	// streamed read-once from global via streaming_load; MFMA vs VMEM are pinned via
2128	// sched_group_barrier so the matrix unit is not starved (§2.11). Sub-16 K (the
2129	// grokking head_dim=4) zero-pads inside the K loop.
2130	__device__ __forceinline__ void mfma_tile_16x16(
2131	    const short* __restrict__ A,   // [M, K] row-major bf16 bits
2132	    const short* __restrict__ W,   // [N, K] row-major bf16 bits  (= Bᵀ)
2133	    float*       __restrict__ C,   // [M, N] row-major f32
2134	    int M, int N, int K,
2135	    int tile_row, int tile_col)    // 16-aligned output-tile origin
2136	{
2137	    const int lane = static_cast<int>(threadIdx.x) % kWave;
2138	    const int half = lane / 16;        // which 16-K group this lane feeds (0..3)
2139	    const int idx  = lane % 16;        // row (for A) / col (for W) within the tile
2140	
2141	    float acc[4] = {0.f, 0.f, 0.f, 0.f};
2142	
2143	    const int aRow = tile_row + idx;   // A row this lane streams
2144	    const int bCol = tile_col + idx;   // W row (= output col) this lane streams
2145	
2146	    for (int k0 = 0; k0 < K; k0 += 16) {
2147	        short af[4], bf[4];
2148	        #pragma unroll
2149	        for (int j = 0; j < 4; ++j) {
2150	            int k = k0 + half * 4 + j;   // 64 lanes cover the 16 K-values ×4
2151	            af[j] = (aRow < M && k < K) ? amd::streaming_load(&A[aRow * K + k]) : (short)0;
2152	            bf[j] = (bCol < N && k < K) ? amd::streaming_load(&W[bCol * K + k]) : (short)0;
2153	        }
2154	        amd::mfma_bf16_16x16x16(acc, af, bf);
2155	        amd::sched_group_barrier<0x008, 1>();   // 1 MFMA …
2156	        amd::sched_group_barrier<0x100, 2>();   // … then 2 VMEM reads
2157	    }
2158	
2159	    #pragma unroll
2160	    for (int r = 0; r < 4; ++r) {
2161	        int outRow = tile_row + 4 * half + r;
2162	        int outCol = tile_col + idx;
2163	        if (outRow < M && outCol < N) C[outRow * N + outCol] = acc[r];
2164	    }
2165	}
2166	
2167	// Whole-matrix driver: one wavefront strides the 16×16 output-tile lattice.
2168	__device__ __forceinline__ void mfma_matmul_bf16(
2169	    const short* __restrict__ A, const short* __restrict__ W,
2170	    float* __restrict__ C, int M, int N, int K)
2171	{
2172	    const int tilesM = (M + 15) / 16;
2173	    const int tilesN = (N + 15) / 16;
2174	    const int nTiles = tilesM * tilesN;
2175	    for (int t = 0; t < nTiles; ++t) {
2176	        int tr = (t / tilesN) * 16;
2177	        int tc = (t % tilesN) * 16;
2178	        mfma_tile_16x16(A, W, C, M, N, K, tr, tc);
2179	    }
2180	}
2181	
2182	// ── §5.2  softmax over a score row [0,L) held by this wavefront ───────────────
2183	// Stable softmax: row max via the DPP MAX butterfly (§5.0), exp-sum via
2184	// amd::wave_reduce_add_dpp (§2.6). Each lane owns the strided score columns
2185	// j = lane, lane+64, …; the in-place rescale writes normalized weights back.
2186	// Returns the log-sum-exp (m + log(sum)) for the saved denom.
2187	__device__ __forceinline__ float softmax_row_inplace(
2188	    float* __restrict__ scores_row, int L)
2189	{
2190	    const int lane = static_cast<int>(threadIdx.x) % kWave;
2191	    float m = -1e30f;
2192	    for (int j = lane; j < L; j += kWave) m = dfmaxf(m, scores_row[j]);
2193	    m = wave_reduce_max_dpp(m);                       // §5.0 DPP max butterfly
2194	    float s = 0.f;
2195	    for (int j = lane; j < L; j += kWave) {
2196	        float e = dexpf(scores_row[j] - m);
2197	        scores_row[j] = e;
2198	        s += e;
2199	    }
2200	    s = amd::wave_reduce_add_dpp(s);                  // §2.6 DPP sum butterfly
2201	    float inv_s = 1.f / dfmaxf(s, 1e-12f);
2202	    for (int j = lane; j < L; j += kWave) scores_row[j] *= inv_s;
2203	    return m + dlogf(dfmaxf(s, 1e-12f));
2204	}
2205	
2206	// ── §5.3a  CSA learned-pool compression of K/V into compressed entries ────────
2207	// Compressed entry c pools the window [c*stride, c*stride+win) of the per-token
2208	// projection `tok` [N,D] with the learned per-position weights softmax(compress_w)
2209	// (passed pre-softmaxed in `pool_w` [win]), renormalized over the valid (in-range)
2210	// positions — the CSA learned-pool baked into the score build (vs HCA's mean
2211	// pool). Writes compressed[Nc,D] in f32 (caller packs to bf16 for the MFMA).
2212	__device__ __forceinline__ void csa_pool_compress(
2213	    const short* __restrict__ tok,  // [N, D] bf16 bits
2214	    const float* __restrict__ pool_w,  // [win]  pre-softmaxed learned pool weights
2215	    float* __restrict__ out,        // [Nc, D] f32
2216	    int N, int D, int stride, int win, int Nc)
2217	{
2218	    const int lane = static_cast<int>(threadIdx.x) % kWave;
2219	    for (int cd = lane; cd < Nc * D; cd += kWave) {
2220	        int c = cd / D, d = cd % D;
2221	        float acc = 0.f, wsum = 0.f;
2222	        for (int w = 0; w < win; ++w) {
2223	            int t = c * stride + w;
2224	            if (t < N) {
2225	                float pw = pool_w[w];
2226	                acc  += pw * bf16_to_f32(tok[t * D + d]);
2227	                wsum += pw;
2228	            }
2229	        }
2230	        out[cd] = acc / dfmaxf(wsum, 1e-12f);
2231	    }
2232	}
2233	
2234	// ── §5.4a  HCA mean-pool compression of K/V into compressed entries ───────────
2235	// Compressed entry c is the mean of the valid tokens in [c*stride, c*stride+stride).
2236	__device__ __forceinline__ void hca_mean_compress(
2237	    const short* __restrict__ tok,  // [N, D] bf16 bits
2238	    float* __restrict__ out,        // [Nc, D] f32
2239	    int N, int D, int stride, int Nc)
2240	{
2241	    const int lane = static_cast<int>(threadIdx.x) % kWave;
2242	    for (int cd = lane; cd < Nc * D; cd += kWave) {
2243	        int c = cd / D, d = cd % D;
2244	        float acc = 0.f; int cnt = 0;
2245	        for (int w = 0; w < stride; ++w) {
2246	            int t = c * stride + w;
2247	            if (t < N) { acc += bf16_to_f32(tok[t * D + d]); ++cnt; }
2248	        }
2249	        out[cd] = acc / dfmaxf(static_cast<float>(cnt), 1e-12f);
2250	    }
2251	}
2252	
2253	// ── §5.3  CSA / HCA attention forward (one wavefront per head) ────────────────
2254	// Dense single-head attention over the compressed entries (CSA: the top-k
2255	// selected ones, presented pre-gathered as cK/cV[Lc,D]; HCA: all compressed):
2256	//   S = Q[N,D] · cKᵀ[Lc,D] · scale  (MFMA), per-row DPP softmax, O = P·cV (MFMA).
2257	// The compression (CSA learned-pool / HCA mean-pool) is done by the §5.3a/§5.4a
2258	// helpers into cK/cV before this call; this kernel is the shared attention core.
2259	// q/cK/cV are bf16 bits; scores live in LDS. Returns nothing; writes out[N,D].
2260	__device__ __forceinline__ void attention_core_native(
2261	    const short* __restrict__ q,    // [N, D] bf16 bits
2262	    const short* __restrict__ cK,   // [Lc, D] bf16 bits (compressed keys)
2263	    const short* __restrict__ cV,   // [Lc, D] bf16 bits (compressed values)
2264	    short* __restrict__ out,        // [N, D] bf16 bits
2265	    float* __restrict__ scores,     // LDS scratch, N*Lc floats
2266	    short* __restrict__ pack,       // LDS scratch: Pbf[N*Lc] + Vtb[D*Lc] shorts
2267	    float* __restrict__ ctxf,       // LDS scratch, N*D floats (O accumulator)
2268	    int N, int Lc, int D, float scale)
2269	{
2270	    const int lane = static_cast<int>(threadIdx.x) % kWave;
2271	
2272	    // S = Q·cKᵀ : A=q[N,D], W=cK[Lc,D] (already Kᵀ-layout, contract over D).
2273	    mfma_matmul_bf16(q, cK, scores, N, Lc, D);
2274	    amd::wait_vmcnt0();
2275	
2276	    // scale, then per-row softmax (DPP reductions).
2277	    for (int i = 0; i < N; ++i) {
2278	        for (int j = lane; j < Lc; j += kWave)
2279	            scores[i * Lc + j] *= scale;
2280	        softmax_row_inplace(&scores[i * Lc], Lc);
2281	    }
2282	    amd::workgroup_barrier_release();
2283	
2284	    // O = P·cV : P is [N,Lc] (row-major softmax weights), cV is [Lc,D]. Contract
2285	    // over the key index j. mfma_matmul_bf16 contracts A·Wᵀ, so feed A=P[N,Lc]
2286	    // and W=cVᵀ[D,Lc] (W[d][j] = cV[j][d]); pack P and cVᵀ to bf16 in LDS first.
2287	    short* Pbf = pack;                                   // N*Lc shorts
2288	    short* Vtb = Pbf + N * Lc;                            // D*Lc shorts (cVᵀ)
2289	    for (int idx = lane; idx < N * Lc; idx += kWave)
2290	        Pbf[idx] = f32_to_bf16(scores[idx]);
2291	    for (int idx = lane; idx < Lc * D; idx += kWave) {
2292	        int j = idx / D, d = idx % D;                    // cV[j][d] → cVᵀ[d][j]
2293	        Vtb[d * Lc + j] = cV[j * D + d];
2294	    }
2295	    amd::workgroup_barrier_release();
2296	
2297	    mfma_matmul_bf16(Pbf, Vtb, ctxf, N, D, Lc);          // O[N,D]
2298	    amd::wait_vmcnt0();
2299	    for (int idx = lane; idx < N * D; idx += kWave)
2300	        out[idx] = f32_to_bf16(ctxf[idx]);
2301	}
2302	
2303	// ── §5.5  PEER product-key routing + inline expert MLP (one wavefront/row) ────
2304	// Per-head: project ctx through Wq → split into two halves q_a/q_b; score each
2305	// half against prod_keys_{A,B}[num_keys, half_qd]; pick the top-k per half (small
2306	// k=4, a lane-cooperative selection over num_keys); form the topk×topk candidate
2307	// grid (pair score = a_val + b_val, expert = a_idx*num_keys + b_idx); softmax the
2308	// candidates; run each through its expert MLP (out = Σ W2_e · relu(W1_e · s)) and
2309	// accumulate routing_w · out. Returns the per-element PEER output (Σ over heads /
2310	// num_heads). All for ONE token row owned by this wavefront.
2311	template <int kTopK>
2312	__device__ __forceinline__ float peer_route_row(
2313	    const float* __restrict__ q_a,   // [half_qd]
2314	    const float* __restrict__ q_b,   // [half_qd]
2315	    const short* __restrict__ keys_a,// [num_keys, half_qd] bf16 bits
2316	    const short* __restrict__ keys_b,// [num_keys, half_qd] bf16 bits
2317	    const short* __restrict__ expert_W1,  // [num_experts, expert_hidden] bf16 bits
2318	    const short* __restrict__ expert_W2,  // [num_experts, expert_hidden] bf16 bits
2319	    int num_keys, int half_qd, int expert_hidden)
2320	{
2321	    const int lane = static_cast<int>(threadIdx.x) % kWave;
2322	
2323	    // Per-half top-k selection over num_keys via a lane-cooperative argmax sweep.
2324	    float a_val[kTopK]; int a_idx[kTopK];
2325	    float b_val[kTopK]; int b_idx[kTopK];
2326	    #pragma unroll
2327	    for (int t = 0; t < kTopK; ++t) {
2328	        a_val[t] = -1e30f; a_idx[t] = 0;
2329	        b_val[t] = -1e30f; b_idx[t] = 0;
2330	    }
2331	    // Lane partial: each lane scores a strided subset of keys, then a DPP-style
2332	    // running top-k via repeated wave-max. For the grokking pk_dim=12 this is a
2333	    // tiny scan; we do it with a simple masked repeated-max over num_keys.
2334	    for (int t = 0; t < kTopK; ++t) {
2335	        // half A
2336	        float best = -1e30f; int besti = 0;
2337	        for (int kk = 0; kk < num_keys; ++kk) {
2338	            bool taken = false;
2339	            for (int u = 0; u < t; ++u) if (a_idx[u] == kk) taken = true;
2340	            if (taken) continue;
2341	            float s = 0.f;
2342	            for (int d = 0; d < half_qd; ++d)
2343	                s += q_a[d] * bf16_to_f32(keys_a[kk * half_qd + d]);
2344	            if (s > best) { best = s; besti = kk; }
2345	        }
2346	        a_val[t] = best; a_idx[t] = besti;
2347	        // half B
2348	        best = -1e30f; besti = 0;
2349	        for (int kk = 0; kk < num_keys; ++kk) {
2350	            bool taken = false;
2351	            for (int u = 0; u < t; ++u) if (b_idx[u] == kk) taken = true;
2352	            if (taken) continue;
2353	            float s = 0.f;
2354	            for (int d = 0; d < half_qd; ++d)
2355	                s += q_b[d] * bf16_to_f32(keys_b[kk * half_qd + d]);
2356	            if (s > best) { best = s; besti = kk; }
2357	        }
2358	        b_val[t] = best; b_idx[t] = besti;
2359	    }
2360	
2361	    // Candidate grid: pair score + softmax (max-sub for stability).
2362	    const int kk2 = kTopK * kTopK;
2363	    float pmax = -1e30f;
2364	    for (int c = 0; c < kk2; ++c) {
2365	        float ps = a_val[c / kTopK] + b_val[c % kTopK];
2366	        pmax = dfmaxf(pmax, ps);
2367	    }
2368	    float psum = 0.f;
2369	    for (int c = 0; c < kk2; ++c)
2370	        psum += dexpf((a_val[c / kTopK] + b_val[c % kTopK]) - pmax);
2371	    float inv_ps = 1.f / dfmaxf(psum, 1e-12f);
2372	
2373	    // Inline expert MLP per candidate; the scalar input is (a_val + b_val).
2374	    float total = 0.f;
2375	    for (int c = 0; c < kk2; ++c) {
2376	        int ia = a_idx[c / kTopK], ib = b_idx[c % kTopK];
2377	        int e  = ia * num_keys + ib;
2378	        float inp = a_val[c / kTopK] + b_val[c % kTopK];
2379	        float rw  = dexpf(inp - pmax) * inv_ps;
2380	        // expert MLP: out = Σ_h W2[e,h] · relu(W1[e,h] · inp). Lane-cooperative
2381	        // over expert_hidden, DPP-reduced.
2382	        float out = 0.f;
2383	        for (int h = lane; h < expert_hidden; h += kWave) {
2384	            float w1 = bf16_to_f32(expert_W1[e * expert_hidden + h]);
2385	            float w2 = bf16_to_f32(expert_W2[e * expert_hidden + h]);
2386	            out += w2 * dreluf(w1 * inp);
2387	        }
2388	        out = amd::wave_reduce_add_dpp(out);
2389	        total += rw * out;
2390	    }
2391	    return total;
2392	}
2393	
2394	// ── §5.6  GRU gates (per element) ────────────────────────────────────────────
2395	// z = σ(Wz·[x;h] + bz) ; r = σ(Wr·[x;h] + br) ;
2396	// h̃ = tanh(Wh·[x; r⊙h] + bh) ; h_new = (1−z)⊙h + z⊙h̃.
2397	// in_dim = peer_input_dim, hidden = gru_hidden; xh is [in_dim+hidden]. One
2398	// wavefront computes the `hidden` outputs for one element row (lane-strided over
2399	// the hidden units; each unit dots the [in_dim+hidden] concat row of W).
2400	__device__ __forceinline__ void gru_gate_row(
2401	    const float* __restrict__ x,    // [in_dim]
2402	    const float* __restrict__ h,    // [hidden]
2403	    const short* __restrict__ Wz,   // [hidden, in_dim+hidden] bf16 bits
2404	    const float* __restrict__ bz,   // [hidden]
2405	    const short* __restrict__ Wr, const float* __restrict__ br,
2406	    const short* __restrict__ Wh, const float* __restrict__ bh,
2407	    float* __restrict__ h_new,      // [hidden] out
2408	    float* __restrict__ rscratch,   // [hidden] scratch for r⊙h
2409	    int in_dim, int hidden)
2410	{
2411	    const int lane = static_cast<int>(threadIdx.x) % kWave;
2412	    const int cat = in_dim + hidden;
2413	    // z and r gates.
2414	    for (int u = lane; u < hidden; u += kWave) {
2415	        float zacc = bz[u], racc = br[u];
2416	        for (int j = 0; j < in_dim; ++j) {
2417	            float xj = x[j];
2418	            zacc += bf16_to_f32(Wz[u * cat + j]) * xj;
2419	            racc += bf16_to_f32(Wr[u * cat + j]) * xj;
2420	        }
2421	        for (int j = 0; j < hidden; ++j) {
2422	            float hj = h[j];
2423	            zacc += bf16_to_f32(Wz[u * cat + in_dim + j]) * hj;
2424	            racc += bf16_to_f32(Wr[u * cat + in_dim + j]) * hj;
2425	        }
2426	        float r = dsigmoidf(racc);
2427	        rscratch[u] = r * h[u];                // r⊙h for h̃
2428	        h_new[u]    = dsigmoidf(zacc);         // stash z in h_new temporarily
2429	    }
2430	    amd::workgroup_barrier_release();
2431	    // h̃ and the convex update.
2432	    for (int u = lane; u < hidden; u += kWave) {
2433	        float hacc = bh[u];
2434	        for (int j = 0; j < in_dim; ++j)
2435	            hacc += bf16_to_f32(Wh[u * cat + j]) * x[j];
2436	        for (int j = 0; j < hidden; ++j)
2437	            hacc += bf16_to_f32(Wh[u * cat + in_dim + j]) * rscratch[j];
2438	        float htilde = dtanhf(hacc);
2439	        float z = h_new[u];
2440	        h_new[u] = (1.f - z) * h[u] + z * htilde;
2441	    }
2442	}
