2450	// LDS byte budget for one attention head (host computes this for the launch).
2451	// scores[N*Lc] f32 + ctx[N*D] f32 + pack(Pbf[N*Lc]+Vtb[D*Lc]) bf16; ≤ 64 KB.
2452	__device__ __forceinline__ int sg2_attn_lds_bytes(int N, int Lc, int D) {
2453	    int sc  = (N * Lc + N * D) * (int)sizeof(float);
2454	    int pk  = (N * Lc + D * Lc) * (int)sizeof(short);
2455	    return sc + pk;
2456	}
