2458	// CSA: compress (learned-pool) the per-head pre-gathered window K/V then attend.
2459	// Here cK/cV are the already-selected compressed entries [Lc,D] (host gathered
2460	// the top-k + window union); the kernel runs the shared attention core.
2461	template <int kHeadDimT>
2462	__global__ void sg2_csa_attention_fwd_mfma(
2463	    const short* __restrict__ q,    // [N, D]
2464	    const short* __restrict__ cK,   // [Lc, D] selected compressed keys
2465	    const short* __restrict__ cV,   // [Lc, D] selected compressed values
2466	    short* __restrict__ out,        // [N, D]
2467	    int N, int Lc, float scale)
2468	{
2469	    extern __shared__ float lds[];
2470	    const int D = kHeadDimT;
2471	    float* scores = lds;                       // N*Lc f32
2472	    float* ctxf   = scores + N * Lc;           // N*D f32
2473	    short* pack   = reinterpret_cast<short*>(ctxf + N * D);  // (N*Lc + D*Lc) shorts
2474	    attention_core_native(q, cK, cV, out, scores, pack, ctxf, N, Lc, D, scale);
2475	}
2476	
2477	// HCA: mean-pool compress then dense-attend over all compressed entries.
2478	template <int kHeadDimT>
2479	__global__ void sg2_hca_attention_fwd_mfma(
2480	    const short* __restrict__ q,    // [N, D]
2481	    const short* __restrict__ k,    // [N, D] raw per-token keys
2482	    const short* __restrict__ v,    // [N, D] raw per-token values
2483	    short* __restrict__ out,        // [N, D]
2484	    int N, int stride, float scale)
2485	{
2486	    extern __shared__ float lds[];
2487	    const int D = kHeadDimT;
2488	    const int Nc = (N + stride - 1) / stride;
2489	    // Compress K/V into LDS (f32), then pack to bf16 for the MFMA attention core.
2490	    float* cKf    = lds;                        // Nc*D f32
2491	    float* cVf    = cKf + Nc * D;               // Nc*D f32
2492	    float* scores = cVf + Nc * D;               // N*Nc f32
2493	    float* ctxf   = scores + N * Nc;            // N*D f32
2494	    short* pack   = reinterpret_cast<short*>(ctxf + N * D);
2495	    short* cKb    = pack;                        // Nc*D shorts
2496	    short* cVb    = cKb + Nc * D;                // Nc*D shorts
2497	    short* corepk = cVb + Nc * D;               // (N*Nc + D*Nc) shorts for the core
2498	    const int lane = static_cast<int>(threadIdx.x) % kWave;
2499	
2500	    hca_mean_compress(k, cKf, N, D, stride, Nc);
2501	    hca_mean_compress(v, cVf, N, D, stride, Nc);
2502	    amd::workgroup_barrier_release();
2503	    for (int idx = lane; idx < Nc * D; idx += kWave) {
2504	        cKb[idx] = f32_to_bf16(cKf[idx]);
2505	        cVb[idx] = f32_to_bf16(cVf[idx]);
2506	    }
2507	    amd::workgroup_barrier_release();
2508	    attention_core_native(q, cKb, cVb, out, scores, corepk, ctxf, N, Nc, D, scale);
2509	}
