2511	// PEER routing: one wavefront per token row, single head (host loops heads and
2512	// accumulates / divides by num_heads). q_a/q_b are the pre-split projected query
2513	// halves for this row.
2514	__global__ void sg2_peer_route_kernel(
2515	    const float* __restrict__ q_a, const float* __restrict__ q_b,
2516	    const short* __restrict__ keys_a, const short* __restrict__ keys_b,
2517	    const short* __restrict__ expert_W1, const short* __restrict__ expert_W2,
2518	    float* __restrict__ peer_out,   // [N] accumulated
2519	    int num_keys, int half_qd, int expert_hidden)
2520	{
2521	    const int row = static_cast<int>(blockIdx.x);
2522	    float r = peer_route_row<4>(
2523	        q_a + row * half_qd, q_b + row * half_qd,
2524	        keys_a, keys_b, expert_W1, expert_W2,
2525	        num_keys, half_qd, expert_hidden);
2526	    if ((static_cast<int>(threadIdx.x) % kWave) == 0) peer_out[row] = r;
2527	}
