2529	// GRU gates: one wavefront per element row.
2530	__global__ void sg2_gru_gate_kernel(
2531	    const float* __restrict__ x,    // [N, in_dim]
2532	    const float* __restrict__ h,    // [N, hidden]
2533	    const short* __restrict__ Wz, const float* __restrict__ bz,
2534	    const short* __restrict__ Wr, const float* __restrict__ br,
2535	    const short* __restrict__ Wh, const float* __restrict__ bh,
2536	    float* __restrict__ h_new,      // [N, hidden]
2537	    int in_dim, int hidden)
