2605	// Stage-1 NaN/Inf gradient sanitization (mirror of sm_90 sg_sanitize_grad).
2606	// Identity unless built with -DSG_SANITIZE_NONFINITE=1; applied on the AdamW
2607	// apply path's grad read only. Default behavior is byte-identical when OFF.
2608	#ifndef SG_SANITIZE_NONFINITE
2609	#define SG_SANITIZE_NONFINITE 0
2610	#endif
2611	__device__ __forceinline__ float sg2_sanitize_grad(float g) {
2612	#if SG_SANITIZE_NONFINITE
2613	    return __builtin_isfinite(g) ? g : 0.0f;
2614	#else
2615	    return g;
2616	#endif
2617	}
