2619	// Identical per-element apply (used by both the f32x4 lanes and the scalar tail).
2620	__device__ __forceinline__ float sg2_adam_apply_elem(
2621	    float* __restrict__ pp, float* __restrict__ pm, float* __restrict__ pv,
2622	    float g_i, float lr, float beta1, float beta2, float eps, float wd,
2623	    float bc1, float bc2)
2624	{
2625	    float m = beta1 * (*pm) + (1.0f - beta1) * g_i;
2626	    float v = beta2 * (*pv) + (1.0f - beta2) * g_i * g_i;
2627	    *pm = m;
2628	    *pv = v;
2629	    float m_hat = m / bc1;
2630	    float v_hat = v / bc2;
2631	    float denom = __builtin_sqrtf(v_hat) + eps;
2632	    float update = m_hat / denom + wd * (*pp);
2633	    return (*pp) - lr * update;
2634	}
