2636	template <typename ParamT, typename GradT>
2637	SG_KERNEL_BOUNDS(256, 8) void sg2_gfx942_adam_apply(
2638	    ParamT* __restrict__ param, float* __restrict__ exp_avg,
2639	    float* __restrict__ exp_avg_sq, const GradT* __restrict__ grad,
2640	    float lr, float beta1, float beta2, float eps, float wd,
2641	    float bc1, float bc2, int64_t N)
2642	{
2643	    // 64-bit grid-stride indexing (Stage 1): cast BEFORE the multiply.
2644	    const int64_t gtid   = static_cast<int64_t>(blockIdx.x) * blockDim.x
2645	                       + threadIdx.x;
2646	    const int64_t stride = static_cast<int64_t>(gridDim.x) * blockDim.x;
2647	    const int64_t n4     = N & ~static_cast<int64_t>(3);   // largest mult of 4 <= N
2648	
2649	    // Vectorized body: 4 contiguous floats / iter via f32x4 (128-bit access).
2650	    // NONTEMPORAL POLICY (matches adamw_gfx942): grad is read-once this step →
2651	    // streaming (nontemporal, L2-bypass); exp_avg / exp_avg_sq are recurring
2652	    // STATE (read+written every step, reused next step) → CACHED; param is read
2653	    // once then written once → cached load + streaming store.
2654	    for (int64_t base = gtid * 4; base < n4; base += stride * 4) {
2655	        f32x4 pv4 = amd_apply::cached_load(reinterpret_cast<const f32x4*>(param + base));
2656	        f32x4 mv4 = amd_apply::cached_load(reinterpret_cast<const f32x4*>(exp_avg + base));
2657	        f32x4 vv4 = amd_apply::cached_load(reinterpret_cast<const f32x4*>(exp_avg_sq + base));
2658	        f32x4 gv4 = amd_apply::streaming_load(reinterpret_cast<const f32x4*>(grad + base));
2659	        f32x4 ov4;
2660	        #pragma unroll
2661	        for (int j = 0; j < 4; ++j) {
2662	            float pj = pv4[j], mj = mv4[j], vj = vv4[j];
2663	            ov4[j] = sg2_adam_apply_elem(&pj, &mj, &vj, sg2_sanitize_grad(gv4[j]),
2664	                                         lr, beta1, beta2, eps, wd, bc1, bc2);
2665	            mv4[j] = mj;
2666	            vv4[j] = vj;
2667	        }
2668	        amd_apply::cached_store(reinterpret_cast<f32x4*>(exp_avg + base), mv4);
2669	        amd_apply::cached_store(reinterpret_cast<f32x4*>(exp_avg_sq + base), vv4);
2670	        amd_apply::streaming_store(reinterpret_cast<f32x4*>(param + base), ov4);
2671	    }
2672	
2673	    // Scalar tail: the n%4 remainder, identical per-element function.
2674	    for (int64_t i = n4 + gtid; i < N; i += stride) {
2675	        float pi = param[i], mi = exp_avg[i], vi = exp_avg_sq[i];
2676	        float out = sg2_adam_apply_elem(&pi, &mi, &vi, sg2_sanitize_grad(grad[i]),
2677	                                        lr, beta1, beta2, eps, wd, bc1, bc2);
2678	        exp_avg[i]    = mi;
2679	        exp_avg_sq[i] = vi;
2680	        param[i]      = out;
2681	    }
2682	}
